-- Volume 1: Trạm Hồn Hệ (Treo Cổ Quỷ)
INSERT INTO bach_quy_am (display_order, volume_number, volume_name, volume_subtitle, volume_tagline, volume_traits, volume_signs, volume_taboo, volume_vuc_name, volume_vuc_desc, name, classification, danger_level, brief_description, looi_phan, duyen_sinh, quy_tinh, quy_luat, quy_vuc, tu_huyet, pha_phap, di_van) VALUES
(1, 1, 'TRẠM HỒN HỆ', '一 · TREO CỔ QUỶ', 'Dây treo một mạng, oán giữ một hồn. Hồn không chịu tan, dây tất tìm người thế mạng.', 'Ký sinh vào dây thừng, xà nhà, cây cổ thụ, cột hành hình, giếng treo cổ hoặc nơi xảy ra nhiều vụ thắt cổ. Oán khí càng lâu năm, dây càng khó bị phá hủy.', 'Dây thừng tự rung dù không gió; tiếng cổ bị siết trong đêm; tiếng chân kéo lê trần nhà; lạnh gáy như có vật chạm vào.', 'Thấy dây chớ ngẩng đầu. Nghe gọi chớ quay cổ. Thấy thòng lọng trước cửa, tuyệt đối không bước qua.', 'Thòng Lọng', 'Mọi vật dạng dây (dây điện, dây rèm, dây giày, tóc, vết nứt tường) đều hóa thành thòng lọng. Nhìn thấy dây của mình, quy luật tử vong bắt đầu.', 'Dây Thòng Lọng Quỷ', 'Trạm Hồn Hệ', 'Du Hồn', 'Quỷ của thòng lọng và tử tục thế mạng', 'Nó không có tay. Nhưng dây trong tay nó, đều có thể giết người.', 'Sinh ra từ sợi dây trực tiếp tước đoạt mạng sống. Thi thể tháo xuống nhưng dây bỏ lại, âm khí tích tụ hóa quỷ.', 'Không chủ động truy sát mà thích chọn người. Nạn nhân liên tục nhìn thấy thòng lọng ở những nơi vô lý.', 'Nhìn thấy dây 3 lần — bị đánh dấu. Chạm vào dây — mất sinh khí. Tự tay buộc dây — tử kỳ đến.', '【Thòng Lọng Vực】 — Mọi vật dạng dây trở thành chi thể của quỷ.', 'Sợi dây gốc ban đầu.', 'Chưa cập nhật', 'Có người chém đứt mười sợi dây mà vẫn chết. Bởi thứ cần chém chưa bao giờ là sợi dây trên cổ hắn.'),
(2, 1, 'TRẠM HỒN HỆ', '一 · TREO CỔ QUỶ', 'Dây treo một mạng, oán giữ một hồn. Hồn không chịu tan, dây tất tìm người thế mạng.', 'Ký sinh vào dây thừng, xà nhà, cây cổ thụ, cột hành hình, giếng treo cổ hoặc nơi xảy ra nhiều vụ thắt cổ. Oán khí càng lâu năm, dây càng khó bị phá hủy.', 'Dây thừng tự rung dù không gió; tiếng cổ bị siết trong đêm; tiếng chân kéo lê trần nhà; lạnh gáy như có vật chạm vào.', 'Thấy dây chớ ngẩng đầu. Nghe gọi chớ quay cổ. Thấy thòng lọng trước cửa, tuyệt đối không bước qua.', 'Thòng Lọng', 'Mọi vật dạng dây (dây điện, dây rèm, dây giày, tóc, vết nứt tường) đều hóa thành thòng lọng. Nhìn thấy dây của mình, quy luật tử vong bắt đầu.', 'Trường Thiệt Quỷ', 'Trạm Hồn Hệ', 'Du Hồn', 'Lưỡi dài ba thước, gọi tên người chết', 'Lưỡi dài ba thước, gọi tên người chết.', 'Treo Cổ Quỷ hấp thu quá nhiều oán khí vùng cổ và miệng biến dị thành.', 'Thích gọi tên người sống. Không rõ giọng phát ra từ đâu.', 'Nghe gọi tên — không được đáp. Nếu đáp, tiếng nói biến thành "lời nhận", Quỷ có quyền xâm nhập giấc mộng.', '【Dạ Ngữ Vực】 — Không gian tràn ngập tiếng thì thầm, không phân biệt nổi tiếng người hay tiếng quỷ.', 'Chiếc lưỡi quỷ.', 'Chưa cập nhật', 'Nó gọi tên ngươi một lần là thử. Gọi hai lần là dụ. Gọi ba lần — là đã biết ngươi ở đâu.'),
(3, 1, 'TRẠM HỒN HỆ', '一 · TREO CỔ QUỶ', 'Dây treo một mạng, oán giữ một hồn. Hồn không chịu tan, dây tất tìm người thế mạng.', 'Ký sinh vào dây thừng, xà nhà, cây cổ thụ, cột hành hình, giếng treo cổ hoặc nơi xảy ra nhiều vụ thắt cổ. Oán khí càng lâu năm, dây càng khó bị phá hủy.', 'Dây thừng tự rung dù không gió; tiếng cổ bị siết trong đêm; tiếng chân kéo lê trần nhà; lạnh gáy như có vật chạm vào.', 'Thấy dây chớ ngẩng đầu. Nghe gọi chớ quay cổ. Thấy thòng lọng trước cửa, tuyệt đối không bước qua.', 'Thòng Lọng', 'Mọi vật dạng dây (dây điện, dây rèm, dây giày, tóc, vết nứt tường) đều hóa thành thòng lọng. Nhìn thấy dây của mình, quy luật tử vong bắt đầu.', 'Thế Mệnh Quỷ', 'Trạm Hồn Hệ', 'Oán Hồn', 'Một người chết, một người thế. Một người thế, lại cần người khác thay.', 'Một người chết, một người thế. Một người thế, lại cần người khác thay.', 'Hình thành sau khi Treo Cổ Quỷ hoàn thành nhiều lần dụ người sống thay thế cái chết của mình.', 'Không giết trực tiếp mà "trao cái chết". Nạn nhân liên tục gặp điềm báo tử vong.', 'Người càng sợ chết, quy luật phát động càng nhanh.', '【Thế Mệnh Vực】 — Mỗi người bước vào đều nhìn thấy xác chết tương lai của chính mình.', 'Chuỗi nhân quả của những người từng bị thế mạng.', 'Chưa cập nhật', 'Đừng hỏi ai là người đầu tiên chết. Hãy hỏi ai là người đầu tiên sống thay cho kẻ chết.'),
(4, 1, 'TRẠM HỒN HỆ', '一 · TREO CỔ QUỶ', 'Dây treo một mạng, oán giữ một hồn. Hồn không chịu tan, dây tất tìm người thế mạng.', 'Ký sinh vào dây thừng, xà nhà, cây cổ thụ, cột hành hình, giếng treo cổ hoặc nơi xảy ra nhiều vụ thắt cổ. Oán khí càng lâu năm, dây càng khó bị phá hủy.', 'Dây thừng tự rung dù không gió; tiếng cổ bị siết trong đêm; tiếng chân kéo lê trần nhà; lạnh gáy như có vật chạm vào.', 'Thấy dây chớ ngẩng đầu. Nghe gọi chớ quay cổ. Thấy thòng lọng trước cửa, tuyệt đối không bước qua.', 'Thòng Lọng', 'Mọi vật dạng dây (dây điện, dây rèm, dây giày, tóc, vết nứt tường) đều hóa thành thòng lọng. Nhìn thấy dây của mình, quy luật tử vong bắt đầu.', 'Lương Thượng Quỷ', 'Trạm Hồn Hệ', 'Oán Hồn', 'Nó ở trên đầu ngươi. Nhưng cái chết lại rơi xuống từ trần nhà.', 'Nó ở trên đầu ngươi. Nhưng cái chết lại rơi xuống từ trần nhà.', 'Hình thành tại xà nhà từng treo thi thể nhiều năm.', 'Trốn trên trần nhà, chờ đợi mồi.', 'Chỉ xuất hiện và tấn công khi có người nằm ngủ ngay dưới xà ngang.', '【Lương Hạ Vực】 — Trần nhà và mặt đất đổi chỗ. Người bước đi tưởng trên nền nhưng đang tiến về phía mái.', 'Xà ngang nguyên thủy nhiễm âm khí.', 'Chưa cập nhật', 'Nếu nửa đêm nghe tiếng chân trên trần, đừng nghĩ đó là người đi.'),
(5, 1, 'TRẠM HỒN HỆ', '一 · TREO CỔ QUỶ', 'Dây treo một mạng, oán giữ một hồn. Hồn không chịu tan, dây tất tìm người thế mạng.', 'Ký sinh vào dây thừng, xà nhà, cây cổ thụ, cột hành hình, giếng treo cổ hoặc nơi xảy ra nhiều vụ thắt cổ. Oán khí càng lâu năm, dây càng khó bị phá hủy.', 'Dây thừng tự rung dù không gió; tiếng cổ bị siết trong đêm; tiếng chân kéo lê trần nhà; lạnh gáy như có vật chạm vào.', 'Thấy dây chớ ngẩng đầu. Nghe gọi chớ quay cổ. Thấy thòng lọng trước cửa, tuyệt đối không bước qua.', 'Thòng Lọng', 'Mọi vật dạng dây (dây điện, dây rèm, dây giày, tóc, vết nứt tường) đều hóa thành thòng lọng. Nhìn thấy dây của mình, quy luật tử vong bắt đầu.', 'Thụ Ỷ Quỷ', 'Trạm Hồn Hệ', 'Lệ Quỷ', 'Cây không biết treo người. Nhưng người chết trên cây, cây sẽ nhớ.', 'Cây không biết treo người. Nhưng người chết trên cây, cây sẽ nhớ.', 'Sinh ra từ người chết treo trên cây cổ thụ cô quạnh.', 'Biến toàn bộ cành tán cây thành dây thắt cổ.', 'Dùng cành cây biến hình thành thòng lọng để siết cổ kẻ đi qua.', '【Quỷ Thụ Lâm】 — Toàn bộ cây cối trong rừng trở thành tay chân của quỷ.', 'Rễ chính ôm lấy hài cốt đầu tiên.', 'Chưa cập nhật', 'Trong rừng nghe người quen gọi tên, đừng đáp. Người ấy nếu thật sự ở đó, đã chẳng gọi ngươi từ trên cây.'),

-- Volume 2: Thủy Hệ (Thủy Quỷ)
(6, 2, 'THỦY HỆ', '二 · THỦY QUỶ', 'Người chết dưới nước, hồn khó lên bờ. Nước giữ xác, oán giữ hồn, người sống trở thành vật thế.', 'Sinh từ nước chôn mạng (sông, hồ, đầm lầy, giếng). Nước càng sâu, oán khí càng nặng, quỷ càng khó tiêu diệt.', 'Mặt nước không phản chiếu bầu trời; nước lạnh bất thường; nghe tiếng gọi từ giữa sông; xuất hiện tóc/bàn tay dưới nước; cá chết hàng loạt.', 'Nghe tiếng gọi dưới nước, chớ đáp. Có người chết kéo chân, chớ nắm tay họ.', 'Nịch Hồn', 'Mặt nước phía trên biến mất, bốn phía biến thành đáy vực sâu thăm thẳm.', 'Nịch Thủy Quỷ', 'Thủy Hệ', 'Du Hồn', 'Người chết đuối không biết mình đã chết, chỉ biết tìm một người khác xuống nước', 'Người chết đuối không biết mình đã chết, chỉ biết tìm một người khác xuống nước.', 'Người chết chìm không tìm thấy xác, bị đẩy xuống nước hoặc chết đuối oan khuất.', 'Không rời thủy vực, bắt chước tiếng kêu cứu dụ người sống đến gần rồi kéo chân dìm chết.', 'Mất một mạng dưới nước — phải bắt một mạng sống thay thế.', '【Nịch Hồn Vực】 — Người bước vào mất phương hướng hoàn toàn dưới nước.', 'Hài cốt hoặc di vật cuối cùng của nạn nhân.', 'Chưa cập nhật', 'Người kéo chân ngươi dưới nước chưa chắc muốn giết ngươi. Có khi nó chỉ muốn ngươi ở lại thay nó.'),
(7, 2, 'THỦY HỆ', '二 · THỦY QUỶ', 'Người chết dưới nước, hồn khó lên bờ. Nước giữ xác, oán giữ hồn, người sống trở thành vật thế.', 'Sinh từ nước chôn mạng (sông, hồ, đầm lầy, giếng). Nước càng sâu, oán khí càng nặng, quỷ càng khó tiêu diệt.', 'Mặt nước không phản chiếu bầu trời; nước lạnh bất thường; nghe tiếng gọi từ giữa sông; xuất hiện tóc/bàn tay dưới nước; cá chết hàng loạt.', 'Nghe tiếng gọi dưới nước, chớ đáp. Có người chết kéo chân, chớ nắm tay họ.', 'Nịch Hồn', 'Mặt nước phía trên biến mất, bốn phía biến thành đáy vực sâu thăm thẳm.', 'Tỉnh Quỷ', 'Thủy Hệ', 'Du Hồn', 'Giếng sâu không đáng sợ. Đáng sợ là dưới giếng có người biết tên ngươi.', 'Giếng sâu không đáng sợ. Đáng sợ là dưới giếng có người biết tên ngươi.', 'Thi thể bị ném xuống giếng hoặc chết oan dưới đáy giếng.', 'Ít khi lộ diện, giả giọng người thân (cha, mẹ, con cái) dụ nạn nhân nhìn xuống.', 'Nghe tiếng gọi → Nhìn xuống giếng → Thấy người quen → Gọi tên người dưới giếng = Bị ghi danh.', '【Tỉnh Trung Vực】 — Đáy giếng kéo dài vô tận, người rơi xuống đi qua các tầng ký ức người chết.', 'Hài cốt đầu tiên bị ném xuống giếng.', 'Chưa cập nhật', 'Nếu giếng gọi đúng tên ngươi, đừng đáp. Nếu nó gọi tên người thân ngươi, càng không được đáp.'),
(8, 2, 'THỦY HỆ', '二 · THỦY QUỶ', 'Người chết dưới nước, hồn khó lên bờ. Nước giữ xác, oán giữ hồn, người sống trở thành vật thế.', 'Sinh từ nước chôn mạng (sông, hồ, đầm lầy, giếng). Nước càng sâu, oán khí càng nặng, quỷ càng khó tiêu diệt.', 'Mặt nước không phản chiếu bầu trời; nước lạnh bất thường; nghe tiếng gọi từ giữa sông; xuất hiện tóc/bàn tay dưới nước; cá chết hàng loạt.', 'Nghe tiếng gọi dưới nước, chớ đáp. Có người chết kéo chân, chớ nắm tay họ.', 'Nịch Hồn', 'Mặt nước phía trên biến mất, bốn phía biến thành đáy vực sâu thăm thẳm.', 'Thủy Mãng Quỷ', 'Thủy Hệ', 'Lệ Quỷ', 'Nước nuốt trăm mạng, trăm mạng nuôi một hình.', 'Nước nuốt trăm mạng, trăm mạng nuôi một hình.', 'Thủy Quỷ nuốt quá nhiều sinh hồn, biến dị mất hình người, biến thành dạng đại xà/mãng hình.', 'Bắt cả thủy vực làm lãnh địa. Tự tạo xoáy nước, dòng chảy ngược, lũ giả, sóng ngầm.', 'Bất kỳ ai cướp sinh mạng trong lãnh địa của nó đều phải trả giá bằng mạng sống.', '【Hắc Thủy Vực】 — Toàn bộ dòng nước chuyển màu đen, hóa thành một phần cơ thể quỷ.', 'Thủy Hạch — Nơi ngưng tụ toàn bộ oán khí dưới đáy nước.', 'Chưa cập nhật', 'Nếu mặt sông nổi lên sống lưng như núi, đừng nghĩ đó là sóng.'),
(9, 2, 'THỦY HỆ', '二 · THỦY QUỶ', 'Người chết dưới nước, hồn khó lên bờ. Nước giữ xác, oán giữ hồn, người sống trở thành vật thế.', 'Sinh từ nước chôn mạng (sông, hồ, đầm lầy, giếng). Nước càng sâu, oán khí càng nặng, quỷ càng khó tiêu diệt.', 'Mặt nước không phản chiếu bầu trời; nước lạnh bất thường; nghe tiếng gọi từ giữa sông; xuất hiện tóc/bàn tay dưới nước; cá chết hàng loạt.', 'Nghe tiếng gọi dưới nước, chớ đáp. Có người chết kéo chân, chớ nắm tay họ.', 'Nịch Hồn', 'Mặt nước phía trên biến mất, bốn phía biến thành đáy vực sâu thăm thẳm.', 'Hà Quỷ', 'Thủy Hệ', 'Hung Sát', 'Một con sông chảy qua trăm năm, cũng có thể chảy qua trăm mạng người.', 'Một con sông chảy qua trăm năm, cũng có thể chảy qua trăm mạng người.', 'Hình thành từ một khúc sông có quá nhiều người chết đuối qua nhiều thế hệ.', 'Lãnh địa cự đại, cực kỳ căm ghét người sống xâm phạm hoặc làm uế dòng nước.', 'Người chết trong sông phải ở lại sông. Thi thể bị vớt lên bất hợp pháp sẽ chọc giận Hà Quỷ.', '【Hoàng Tuyền Hà】 — Nước sông hóa đen nghìn thước, sống chết ranh giới bị xóa bỏ.', 'Khúc sông đầu tiên phát sinh oán khí.', 'Chưa cập nhật', 'Sông không giữ người. Là người chết giữ sông.'),
(10, 2, 'THỦY HỆ', '二 · THỦY QUỶ', 'Người chết dưới nước, hồn khó lên bờ. Nước giữ xác, oán giữ hồn, người sống trở thành vật thế.', 'Sinh từ nước chôn mạng (sông, hồ, đầm lầy, giếng). Nước càng sâu, oán khí càng nặng, quỷ càng khó tiêu diệt.', 'Mặt nước không phản chiếu bầu trời; nước lạnh bất thường; nghe tiếng gọi từ giữa sông; xuất hiện tóc/bàn tay dưới nước; cá chết hàng loạt.', 'Nghe tiếng gọi dưới nước, chớ đáp. Có người chết kéo chân, chớ nắm tay họ.', 'Nịch Hồn', 'Mặt nước phía trên biến mất, bốn phía biến thành đáy vực sâu thăm thẳm.', 'Chiểu Quỷ', 'Thủy Hệ', 'Hung Sát', 'Bùn giữ xác, xác giữ hồn.', 'Bùn giữ xác, xác giữ hồn.', 'Người chết bị vùi lấp trong bùn lầy, xác không thể phân hủy hay thoát ra.', 'Không chủ động truy đuổi, khiến mặt đất tự biến thành bùn lầy nuốt chửng nạn nhân.', 'Nạn nhân càng giãy giụa càng chìm nhanh; nạn nhân càng sợ hãi, Quỷ Vực càng lan rộng.', '【Nê Chiểu Vực】 — Biến toàn bộ mặt đất cứng xung quanh thành đầm lầy chết chóc.', 'Thi thể đầu tiên nằm sâu nhất dưới lòng đất.', 'Chưa cập nhật', 'Đầm lầy không có tiếng kêu. Bởi những người kêu đều đã chìm.'),

-- Volume 3: Âm Duyên Hệ (Tân Nương Quỷ)
(11, 3, 'ÂM DUYÊN HỆ', '三 · TÂN NƯƠNG QUỶ', 'Hỷ phục không cởi, hôn thư chưa đoạn. Người chết một lần, duyên chết chẳng xong.', 'Sinh từ hôn nhân oan khuất, âm hôn cưỡng ép, bội ước, táng mạng đúng ngày cưới.', 'Tiếng kèn gõ trống giữa đêm; mùi hương phấn hoa cưới nồng nặc; hoa hỷ đỏ xuất hiện trước cửa; vết máu trên áo cưới.', 'Gặp kiệu đỏ giữa đêm, chớ nhìn rèm.', 'Hỷ Đường', 'Căn nhà cưới linh đình gấm vóc nhưng không có lối thoát.', 'Hồng Y Quỷ', 'Âm Duyên Hệ', 'Du Hồn', 'Áo đỏ không đáng sợ. Đáng sợ là người mặc áo đỏ đã chết từ nhiều năm trước.', 'Áo đỏ không đáng sợ. Đáng sợ là người mặc áo đỏ đã chết từ nhiều năm trước.', 'Nữ tử mang uất hận thâm sâu, chết oan đúng lúc đang mặc hỷ phục áo đỏ.', 'Chuyển hóa hỷ khí thành sát khí, truy tìm người có "duyên phu thê" để ép chết.', 'Nhận bất kỳ hỷ vật nào (trâm, bao lì xì, hoa) của nó sẽ trở thành tân lang/tân nương bị chọn.', '【Hỷ Đường Vực】 — Bãi không gian biến thành đường cưới phủ kín vải đỏ.', 'Bộ hỷ phục nguyên bản mặc trên người lúc chết.', 'Chưa cập nhật', 'Thấy áo đỏ bay trong gió đêm, chớ khen đẹp. Đó là gấm liệm của kẻ chết oan.'),
(12, 3, 'ÂM DUYÊN HỆ', '三 · TÂN NƯƠNG QUỶ', 'Hỷ phục không cởi, hôn thư chưa đoạn. Người chết một lần, duyên chết chẳng xong.', 'Sinh từ hôn nhân oan khuất, âm hôn cưỡng ép, bội ước, táng mạng đúng ngày cưới.', 'Tiếng kèn gõ trống giữa đêm; mùi hương phấn hoa cưới nồng nặc; hoa hỷ đỏ xuất hiện trước cửa; vết máu trên áo cưới.', 'Gặp kiệu đỏ giữa đêm, chớ nhìn rèm.', 'Hỷ Đường', 'Căn nhà cưới linh đình gấm vóc nhưng không có lối thoát.', 'Minh Hôn Quỷ', 'Âm Duyên Hệ', 'Oán Hồn', 'Hôn thư dưới âm không cần người sống ký.', 'Hôn thư dưới âm không cần người sống ký.', 'Sinh ra từ việc ép buộc kết âm hôn giữa người sống và người chết hoặc hai thi thể.', 'Cưỡng ép người sống hoàn thành toàn bộ nghi thức âm duyên để kéo xuống âm phủ.', 'Vô tình nhận hoặc đụng vào linh vị/hôn thư → Trực tiếp trở thành phối ngẫu.', '【Minh Hôn Đường】 — Không gian hiện ra một đám cưới ma dành riêng cho nạn nhân.', 'Tờ Hôn Thư bằng giấy trang kim.', 'Chưa cập nhật', 'Lụa đỏ buộc cổ tay, sống cùng giường, chết chung huyệt.'),
(13, 3, 'ÂM DUYÊN HỆ', '三 · TÂN NƯƠNG QUỶ', 'Hỷ phục không cởi, hôn thư chưa đoạn. Người chết một lần, duyên chết chẳng xong.', 'Sinh từ hôn nhân oan khuất, âm hôn cưỡng ép, bội ước, táng mạng đúng ngày cưới.', 'Tiếng kèn gõ trống giữa đêm; mùi hương phấn hoa cưới nồng nặc; hoa hỷ đỏ xuất hiện trước cửa; vết máu trên áo cưới.', 'Gặp kiệu đỏ giữa đêm, chớ nhìn rèm.', 'Hỷ Đường', 'Căn nhà cưới linh đình gấm vóc nhưng không có lối thoát.', 'Hoa Kiệu Quỷ', 'Âm Duyên Hệ', 'Oán Hồn', 'Kiệu hoa dừng trước cửa nhà ngươi, không phải để hỏi đường.', 'Kiệu hoa dừng trước cửa nhà ngươi, không phải để hỏi đường.', 'Tân nương chết thảm trên đường đưa dâu do tai nạn, cướp bóc hoặc bị sát hại.', 'Dụ dỗ hoặc cưỡng ép người sống bước lên kiệu hoa.', 'Mở rèm nhìn vào trong kiệu khi kiệu dừng → Bị thu mất sinh hồn.', '【Vô Hồi Kiệu Lộ】 — Con đường đưa dâu dài vô tận không có điểm dừng.', 'Chiếc trâm cài tóc của tân nương.', 'Chưa cập nhật', 'Tiếng kèn cưới nửa đêm không phải đón dâu, là đón hồn.'),
(14, 3, 'ÂM DUYÊN HỆ', '三 · TÂN NƯƠNG QUỶ', 'Hỷ phục không cởi, hôn thư chưa đoạn. Người chết một lần, duyên chết chẳng xong.', 'Sinh từ hôn nhân oan khuất, âm hôn cưỡng ép, bội ước, táng mạng đúng ngày cưới.', 'Tiếng kèn gõ trống giữa đêm; mùi hương phấn hoa cưới nồng nặc; hoa hỷ đỏ xuất hiện trước cửa; vết máu trên áo cưới.', 'Gặp kiệu đỏ giữa đêm, chớ nhìn rèm.', 'Hỷ Đường', 'Căn nhà cưới linh đình gấm vóc nhưng không có lối thoát.', 'Bái Đường Quỷ', 'Âm Duyên Hệ', 'Lệ Quỷ', 'Nhất bái thiên địa, nhị bái cao đường, tam bái... vào quan tài.', 'Nhất bái thiên địa, nhị bái cao đường, tam bái... vào quan tài.', 'Người chết ngay trong lúc đang tiến hành lễ bái đường, chấp niệm nghi lễ chưa thành.', 'Ép buộc bất kỳ ai lọt vào tầm mắt phải thực hiện đủ ba lễ bái đường với nó.', 'Nhất bái — Nhập vực. Nhị bái — Trừ duyên sống. Tam bái — Định mạng chết.', '【Tam Bái Vực】 — Mỗi tiếng hô bái đường vang lên, Quỷ Vực lại sâu thêm một tầng.', 'Bài vị hoặc ảnh thờ tại hỷ đường.', 'Chưa cập nhật', 'Đã lỡ quỳ xuống bái lần thứ nhất, đừng mong đứng dậy bình an.'),
(15, 3, 'ÂM DUYÊN HỆ', '三 · TÂN NƯƠNG QUỶ', 'Hỷ phục không cởi, hôn thư chưa đoạn. Người chết một lần, duyên chết chẳng xong.', 'Sinh từ hôn nhân oan khuất, âm hôn cưỡng ép, bội ước, táng mạng đúng ngày cưới.', 'Tiếng kèn gõ trống giữa đêm; mùi hương phấn hoa cưới nồng nặc; hoa hỷ đỏ xuất hiện trước cửa; vết máu trên áo cưới.', 'Gặp kiệu đỏ giữa đêm, chớ nhìn rèm.', 'Hỷ Đường', 'Căn nhà cưới linh đình gấm vóc nhưng không có lối thoát.', 'Hỷ Sát Quỷ', 'Âm Duyên Hệ', 'Hung Sát', 'Máu đỏ nhuộm áo đỏ, ngày vui hóa ngày tàn.', 'Máu đỏ nhuộm áo đỏ, ngày vui hóa ngày tàn.', 'Hình thành khi một đám cưới biến thành vụ thảm sát kinh hoàng (diệt tộc, cháy nhà).', 'Hấp thụ đồng thời hỷ khí và sát khí để lớn mạnh, biến niềm vui thành sự điên loạn.', 'Nơi nào đông người chúc phúc, hỷ khí càng cao thì Hung Sát phát động càng mạnh.', '【Hỷ Sát Thành】 — Cả khu vực rộng lớn biến thành một hôn lễ máu điên cuồng.', 'Hỷ Sát Hạch — Chiếc đèn lồng đỏ ngâm máu chứa toàn bộ sát khí.', 'Chưa cập nhật', 'Tiếng cười càng lớn, tiếng chém giết vang lên càng đau thương.'),

-- Volume 4: Sát Nghiệp Hệ (Huyết Quỷ)
(16, 4, 'SÁT NGHIỆP HỆ', '四 · HUYẾT QUỶ', 'Máu của một người là thương tích. Máu của trăm người là sát nghiệp.', 'Sinh ra từ nơi tàn sát, chảy máu nhiều, pháp trường, lò sát sinh, vụ thảm sát diệt môn.', 'Mùi tanh nồng đặc quánh; nước hóa thành màu đỏ; tường rỉ máu; không khí nóng rát bốc mùi tủy sống.', 'Có máu không có xác — chớ để máu chạm thân.', 'Huyết Trì', 'Toàn bộ mặt đất biến thành sông máu ngập lúa.', 'Huyết Trì Quỷ', 'Sát Nghiệp Hệ', 'Du Hồn', 'Máu rơi chảy thành ao, oán đọng thành hình.', 'Máu rơi chảy thành ao, oán đọng thành hình.', 'Sinh ra từ các hố máu, ao máu chôn người chết oan thời chiến loạn hoặc dịch bệnh.', 'Thích kéo người sống dìm vào lòng bể máu để tan thịt nát xương.', 'Máu trong bể tuyệt đối không được làm khô; hễ dính máu bể là bị dính chặt.', '【Huyết Trì Vực】 — Bể máu mở rộng nuốt trọn mọi sinh vật xung quanh.', 'Giọt máu tích tụ oán khí đầu tiên ở đáy bể.', 'Chưa cập nhật', 'Đừng bao giờ lội qua vũng nước màu đỏ thẫm trong đền hoang.'),
(17, 4, 'SÁT NGHIỆP HỆ', '四 · HUYẾT QUỶ', 'Máu của một người là thương tích. Máu của trăm người là sát nghiệp.', 'Sinh ra từ nơi tàn sát, chảy máu nhiều, pháp trường, lò sát sinh, vụ thảm sát diệt môn.', 'Mùi tanh nồng đặc quánh; nước hóa thành màu đỏ; tường rỉ máu; không khí nóng rát bốc mùi tủy sống.', 'Có máu không có xác — chớ để máu chạm thân.', 'Huyết Trì', 'Toàn bộ mặt đất biến thành sông máu ngập lúa.', 'Thực Huyết Quỷ', 'Sát Nghiệp Hệ', 'Oán Hồn', 'Máu người sống là rượu ngọt của quỷ.', 'Máu người sống là rượu ngọt của quỷ.', 'Con người lúc sống nghiện uống máu hoặc quỷ bị bỏ đói máu trong ngục tối hẻm hóc.', 'Nhạy cảm cực độ với vết thương hở và mùi máu người sống.', 'Càng có nhiều máu chảy ra ngoài, Thực Huyết Quỷ càng trở nên cuồng bạo.', '【Huyết Thực Vực】 — Mùi máu trong vực làm nạn nhân tự cào rách da thịt mình.', 'Chiếc khẩu mộc/miệng quỷ.', 'Chưa cập nhật', 'Một giọt máu rơi xuống, mười con Thực Huyết Quỷ bò ra.'),
(18, 4, 'SÁT NGHIỆP HỆ', '四 · HUYẾT QUỶ', 'Máu của một người là thương tích. Máu của trăm người là sát nghiệp.', 'Sinh ra từ nơi tàn sát, chảy máu nhiều, pháp trường, lò sát sinh, vụ thảm sát diệt môn.', 'Mùi tanh nồng đặc quánh; nước hóa thành màu đỏ; tường rỉ máu; không khí nóng rát bốc mùi tủy sống.', 'Có máu không có xác — chớ để máu chạm thân.', 'Huyết Trì', 'Toàn bộ mặt đất biến thành sông máu ngập lúa.', 'Huyết Sát Quỷ', 'Sát Nghiệp Hệ', 'Hung Sát', 'Chiết sát người khác, máu nhuộm tâm ma.', 'Chiết sát người khác, máu nhuộm tâm ma.', 'Sinh ra từ kẻ giết người hàng loạt hoặc nạn nhân chết trong cuồng sát thâm thù.', 'Không chỉ hút máu mà còn kích động sát niệm, khiến người sống tự chém giết lẫn nhau.', 'Ai nảy sinh ý định giết người trong vực sẽ bị quỷ cướp lấy sát khí và điều khiển.', '【Sát Huyết Vực】 — Không khí đỏ sẫm kích thích thú tính của mọi sinh linh.', 'Hung khí dùng để thực hiện vụ sát nhân đầu tiên.', 'Chưa cập nhật', 'Kẻ đi săn Huyết Sát Quỷ thường trở thành con bài mới của nó.'),
(19, 4, 'SÁT NGHIỆP HỆ', '四 · HUYẾT QUỶ', 'Máu của một người là thương tích. Máu của trăm người là sát nghiệp.', 'Sinh ra từ nơi tàn sát, chảy máu nhiều, pháp trường, lò sát sinh, vụ thảm sát diệt môn.', 'Mùi tanh nồng đặc quánh; nước hóa thành màu đỏ; tường rỉ máu; không khí nóng rát bốc mùi tủy sống.', 'Có máu không có xác — chớ để máu chạm thân.', 'Huyết Trì', 'Toàn bộ mặt đất biến thành sông máu ngập lúa.', 'Đồ Trường Quỷ', 'Sát Nghiệp Hệ', 'Hung Sát', 'Trăm hình vạn phạt, máu trôi thành dòng.', 'Trăm hình vạn phạt, máu trôi thành dòng.', 'Tích tụ tại các pháp trường, ngục xót thời cổ, nơi xử tử hàng vạn phạm nhân.', 'Tái hiện lại các hình phạt tàn khốc: chém đầu, lăng trì, thiêu sống, xé xác.', 'Người sống bước vào vực lập tức bị mặc định gán cho danh xưng "tội nhân".', '【Đồ Trường Vực】 — Khái niệm pháp trường hiện hình với đầy đủ dụng cụ hành hình.', 'Đài hành hình hoặc trảm đao trung tâm.', 'Chưa cập nhật', 'Đêm thanh vắng nghe tiếng đao rơi trên đá, là lúc Đồ Trường Quỷ xưng vương.'),
(20, 4, 'SÁT NGHIỆP HỆ', '四 · HUYẾT QUỶ', 'Máu của một người là thương tích. Máu của trăm người là sát nghiệp.', 'Sinh ra từ nơi tàn sát, chảy máu nhiều, pháp trường, lò sát sinh, vụ thảm sát diệt môn.', 'Mùi tanh nồng đặc quánh; nước hóa thành màu đỏ; tường rỉ máu; không khí nóng rát bốc mùi tủy sống.', 'Có máu không có xác — chớ để máu chạm thân.', 'Huyết Trì', 'Toàn bộ mặt đất biến thành sông máu ngập lúa.', 'Huyết Hải Quỷ', 'Sát Nghiệp Hệ', 'Quỷ Tướng', 'Một người là máu. Một trăm người là sông. Một vạn người là biển.', 'Một người là máu. Một trăm người là sông. Một vạn người là biển.', 'Đại thành của Huyết Hệ, sinh ra từ chiến trường thảm khốc hoặc họa diệt vong một thành trì.', 'Nuốt trọn mọi thứ vào biển máu, biến tất cả vật chất thành máu đỏ.', 'Thời gian kéo dài càng lâu, sát nghiệp hấp thu càng lớn, sức mạnh tăng theo cấp số nhân.', '【Huyết Hải Vực】 — Biển máu mênh mông đè nát và hòa tan mọi sự sống.', 'Huyết Hạch nằm ẩn sâu trong tâm điểm biển máu.', 'Chưa cập nhật', 'Huyết Hải dâng lên, trời đất không còn màu xanh.'),

-- Volume 5: Tâm Niệm Hệ (Mộng Quỷ)
(21, 5, 'TÂM NIỆM HỆ', '五 · MỘNG QUỶ', 'Quỷ không ở trong mộng. Quỷ khiến ngươi không còn phân biệt được mộng và đời.', 'Xuất hiện khi nạn nhân đi ngủ, suy nhược thần kinh, ôm nỗi sợ thầm kín hoặc tâm ma.', 'Mơ thấy cùng một giấc mơ nhiều lần; tỉnh dậy thấy cơ thể kiệt sức/có vết rạch; không thể phân biệt thực giả.', 'Trong mộng gặp người chết, chớ nhận tay họ.', 'Đại Mộng', 'Mọi quy luật vật lý thế giới thực đều bị bóp méo theo ý quỷ.', 'Yểm Quỷ', 'Tâm Niệm Hệ', 'Du Hồn', 'Đè trên ngực ngươi không phải bóng tối, mà là mười ngón tay lạnh ngắt.', 'Đè trên ngực ngươi không phải bóng tối, mà là mười ngón tay lạnh ngắt.', 'Sinh ra từ hiện tượng bóng đè tích tụ cùng sự sợ hãi tột cùng lúc nửa tỉnh nửa mê.', 'Trèo lên ngực nạn nhân lúc ngủ, khóa chặt cơ thể và hút dần dương khí.', 'Nạn nhân càng hoảng loạn giãy giụa, quỷ đè càng nặng, không thể cất tiếng gọi.', '【Yểm Mộng Vực】 — Không gian căn phòng ngủ bị cô lập hoàn toàn với bên ngoài.', 'Khoảnh khắc nạn nhân ý thức được mình đang nằm mơ (Tỉnh mộng).', 'Chưa cập nhật', 'Đừng bao giờ nằm ngủ ngửa tay lên ngực ở những căn phòng trống.'),
(22, 5, 'TÂM NIỆM HỆ', '五 · MỘNG QUỶ', 'Quỷ không ở trong mộng. Quỷ khiến ngươi không còn phân biệt được mộng và đời.', 'Xuất hiện khi nạn nhân đi ngủ, suy nhược thần kinh, ôm nỗi sợ thầm kín hoặc tâm ma.', 'Mơ thấy cùng một giấc mơ nhiều lần; tỉnh dậy thấy cơ thể kiệt sức/có vết rạch; không thể phân biệt thực giả.', 'Trong mộng gặp người chết, chớ nhận tay họ.', 'Đại Mộng', 'Mọi quy luật vật lý thế giới thực đều bị bóp méo theo ý quỷ.', 'Thực Mộng Quỷ', 'Tâm Niệm Hệ', 'Oán Hồn', 'Ăn hết mộng đẹp, để lại đời tàn.', 'Ăn hết mộng đẹp, để lại đời tàn.', 'Hình thành từ vong linh khao khát những ký ức đẹp đẽ mà khi sống không có được.', 'Chuyên gia ăn các giấc mơ hạnh phúc, hy vọng của con người, bỏ lại sự trống rỗng, trầm cảm.', 'Nạn nhân càng ngủ say trong mơ đẹp thì cơ thể thật ngoài đời càng mau chóng suy kiệt.', '【Thực Mộng Vực】 — Thiền đường biến thành thiên đường ảo ảnh do quỷ dựng lên.', 'Giấc mơ đẹp đầu tiên mà quỷ đã nuốt chửng.', 'Chưa cập nhật', 'Nếu giấc mơ quá hoàn hảo, hãy cẩn thận kẻo không bao giờ tỉnh lại.'),
(23, 5, 'TÂM NIỆM HỆ', '五 · MỘNG QUỶ', 'Quỷ không ở trong mộng. Quỷ khiến ngươi không còn phân biệt được mộng và đời.', 'Xuất hiện khi nạn nhân đi ngủ, suy nhược thần kinh, ôm nỗi sợ thầm kín hoặc tâm ma.', 'Mơ thấy cùng một giấc mơ nhiều lần; tỉnh dậy thấy cơ thể kiệt sức/có vết rạch; không thể phân biệt thực giả.', 'Trong mộng gặp người chết, chớ nhận tay họ.', 'Đại Mộng', 'Mọi quy luật vật lý thế giới thực đều bị bóp méo theo ý quỷ.', 'Mộng Yểm Quỷ', 'Tâm Niệm Hệ', 'Lệ Quỷ', 'Chết trong mơ một lần, ngoài đời bớt một mạng.', 'Chết trong mơ một lần, ngoài đời bớt một mạng.', 'Tích tụ từ những người chết đột ngột do đột quỵ hoặc gặp ác mộng kinh hoàng liên tục.', 'Ép nạn nhân lặp đi lặp lại một viễn cảnh cái chết tàn khốc trong nhiều đêm.', 'Nạn nhân bị thương hoặc chết trong mơ → Cơ thể ngoài đời thật xuất hiện vết thương tương ứng hoặc ngừng thở.', '【Luân Mộng Vực】 — Vòng lặp vô tận của một vụ án tử vong trong mơ.', 'Điểm bất hợp lý duy nhất xuất hiện giữa các vòng lặp giấc mơ.', 'Chưa cập nhật', 'Cổ họng đau sau khi ngủ dậy, có lẽ đêm qua ngươi vừa bị thắt cổ trong mơ.'),
(24, 5, 'TÂM NIỆM HỆ', '五 · MỘNG QUỶ', 'Quỷ không ở trong mộng. Quỷ khiến ngươi không còn phân biệt được mộng và đời.', 'Xuất hiện khi nạn nhân đi ngủ, suy nhược thần kinh, ôm nỗi sợ thầm kín hoặc tâm ma.', 'Mơ thấy cùng một giấc mơ nhiều lần; tỉnh dậy thấy cơ thể kiệt sức/có vết rạch; không thể phân biệt thực giả.', 'Trong mộng gặp người chết, chớ nhận tay họ.', 'Đại Mộng', 'Mọi quy luật vật lý thế giới thực đều bị bóp méo theo ý quỷ.', 'Tâm Ma Quỷ', 'Tâm Niệm Hệ', 'Hung Sát', 'Nỗi sợ của ngươi chính là lưỡi đao của nó.', 'Nỗi sợ của ngươi chính là lưỡi đao của nó.', 'Sinh ra từ cảm giác tội lỗi, sám hối, nỗi sợ hãi thầm kín nhất của tâm trí con người.', 'Hiện hình thành đúng nỗi sợ lớn nhất của nạn nhân (sợ cô độc, sợ lửa, sợ mất người thân).', 'Nạn nhân càng chối bỏ hoặc sợ hãi, thực thể Tâm Ma càng trở nên mạnh mẽ và hung hãn.', '【Tâm Tượng Vực】 — Không gian phản chiếu toàn bộ góc tối trong tâm hồn nạn nhân.', 'Sự chấp nhận và đối diện trực tiếp với nỗi sợ của chính mình.', 'Chưa cập nhật', 'Kẻ thù lớn nhất không phải quỷ dữ ngoài đường, mà là bóng đen trong tim.'),
(25, 5, 'TÂM NIỆM HỆ', '五 · MỘNG QUỶ', 'Quỷ không ở trong mộng. Quỷ khiến ngươi không còn phân biệt được mộng và đời.', 'Xuất hiện khi nạn nhân đi ngủ, suy nhược thần kinh, ôm nỗi sợ thầm kín hoặc tâm ma.', 'Mơ thấy cùng một giấc mơ nhiều lần; tỉnh dậy thấy cơ thể kiệt sức/có vết rạch; không thể phân biệt thực giả.', 'Trong mộng gặp người chết, chớ nhận tay họ.', 'Đại Mộng', 'Mọi quy luật vật lý thế giới thực đều bị bóp méo theo ý quỷ.', 'Mộng Chủ', 'Tâm Niệm Hệ', 'Quỷ Tướng', 'Trong mộng nó là trời.', 'Trong mộng nó là trời.', 'Cấp cao nhất của Mộng Hệ, quỷ đã nuốt vạn giấc mơ và làm chủ quy luật tâm thức.', 'Sửa đổi toàn bộ quy luật vật lý, đảo lộn thực tại, nhốt hàng ngàn sinh hồn vào mộng cảnh.', 'Bất kỳ ai đi ngủ trong phạm vi ảnh hưởng đều lập tức trở thành dân cư dưới quyền Mộng Chủ.', '【Đại Mộng Vực】 — Thế giới giấc mơ rộng lớn như một quốc gia thật sự.', 'Cơ thể ký sinh thật của người bị Mộng Chủ nhập ngoài đời thực.', 'Chưa cập nhật', 'Đừng tỉnh lại... vì khi tỉnh lại, ngươi sẽ thấy thế giới này vốn dĩ đã là mộng.'),

-- Volume 6: Mẫu Chấp Hệ (Quỷ Mẫu)
(26, 6, 'MẪU CHẤP HỆ', '六 · QUỶ MẪU', 'Mẫu tử là duyên. Duyên đứt mà lòng không đoạn, sinh chấp thành quỷ.', 'Sinh từ người mẹ chết khi mang thai, chết khi sinh, mất con hoặc chết để bảo vệ con.', 'Tiếng trẻ khóc ngặt nghẽo đêm khuya; mùi sữa ôi thiu; nôi tự đuôi đung đưa; máu nhuộm bụng dưới.', 'Nghe trẻ khóc ngoài cửa, chớ mở cửa tìm.', 'Vạn Tử Cung', 'Không gian dạ con khổng lồ nuốt chửng kẻ thù vào làm thai nhi.', 'Sản Tử Quỷ', 'Mẫu Chấp Hệ', 'Du Hồn', 'Con chưa kịp chào đời, mẹ đã thành quỷ dữ.', 'Con chưa kịp chào đời, mẹ đã thành quỷ dữ.', 'Sản phụ chết thảm trên bàn đẻ khi đứa trẻ chưa kịp cất tiếng khóc chào đời.', 'Đi lang thang tìm kiếm đứa con chưa từng nhìn thấy mặt, oán khí màng bọc thai cực nặng.', 'Tìm kiếm bất kỳ hình bóng đứa trẻ nào; ai ngăn cản con nó sẽ bị xé xác.', '【Sản Phòng Vực】 — Phòng đẻ đẫm máu tái hiện với tiếng la hét thảm thiết.', 'Kỷ vật hoặc tã lót chuẩn bị cho đứa trẻ chưa sinh.', 'Chưa cập nhật', 'Tiếng rên rỉ trong phòng sinh hoang là lời gọi con của Sản Tử Quỷ.'),
(27, 6, 'MẪU CHẤP HỆ', '六 · QUỶ MẪU', 'Mẫu tử là duyên. Duyên đứt mà lòng không đoạn, sinh chấp thành quỷ.', 'Sinh từ người mẹ chết khi mang thai, chết khi sinh, mất con hoặc chết để bảo vệ con.', 'Tiếng trẻ khóc ngặt nghẽo đêm khuya; mùi sữa ôi thiu; nôi tự đuôi đung đưa; máu nhuộm bụng dưới.', 'Nghe trẻ khóc ngoài cửa, chớ mở cửa tìm.', 'Vạn Tử Cung', 'Không gian dạ con khổng lồ nuốt chửng kẻ thù vào làm thai nhi.', 'Tầm Tử Quỷ', 'Mẫu Chấp Hệ', 'Oán Hồn', 'Con ơi ở đâu, mẹ tìm con khắp chốn.', 'Con ơi ở đâu, mẹ tìm con khắp chốn.', 'Người mẹ hóa dại rồi chết sau khi lạc mất con hoặc con bị bắt cóc/sát hại.', 'Đã mất đi lý trí, đi khắp nơi bắt cóc trẻ em của người sống về làm con mình.', 'Nhìn thấy trẻ em dưới 10 tuổi → Nhầm tưởng là con mình và cướp lấy.', '【Mê Tử Lộ】 — Con đường sương mù mờ ảo dẫn trẻ em đi mất tích.', 'Hài cốt thật của đứa con bị mất năm xưa.', 'Chưa cập nhật', 'Đêm tối chớ để trẻ con chơi một mình, Tầm Tử Quỷ đang đi qua làng.'),
(28, 6, 'MẪU CHẤP HỆ', '六 · QUỶ MẪU', 'Mẫu tử là duyên. Duyên đứt mà lòng không đoạn, sinh chấp thành quỷ.', 'Sinh từ người mẹ chết khi mang thai, chết khi sinh, mất con hoặc chết để bảo vệ con.', 'Tiếng trẻ khóc ngặt nghẽo đêm khuya; mùi sữa ôi thiu; nôi tự đuôi đung đưa; máu nhuộm bụng dưới.', 'Nghe trẻ khóc ngoài cửa, chớ mở cửa tìm.', 'Vạn Tử Cung', 'Không gian dạ con khổng lồ nuốt chửng kẻ thù vào làm thai nhi.', 'Hộ Tử Quỷ', 'Mẫu Chấp Hệ', 'Lệ Quỷ', 'Ai đụng đến con ta, kẻ đó phải chết!', 'Ai đụng đến con ta, kẻ đó phải chết!', 'Người mẹ xả thân chết thảm để bảo vệ đứa con khỏi thiên tai, cướp bóc hay thú dữ.', 'Cực kỳ hung dữ với bất kỳ ai có thái độ hoặc hành vi đe dọa đến trẻ em.', 'Chỉ cần nảy sinh ý định hoặc hành động thương tổn trẻ em → Trở thành mục tiêu bị truy sát tận cùng.', '【Hộ Tử Vực】 — Lớp màng bảo vệ âm khí bất xâm xuyên thủng mọi đòn tấn công.', 'Lời hứa bảo vệ con chưa trọn vẹn.', 'Chưa cập nhật', 'Tình mẫu tử của quỷ dữ đôi khi còn tàn khốc hơn cả ác ma.'),
(29, 6, 'MẪU CHẤP HỆ', '六 · QUỶ MẪU', 'Mẫu tử là duyên. Duyên đứt mà lòng không đoạn, sinh chấp thành quỷ.', 'Sinh từ người mẹ chết khi mang thai, chết khi sinh, mất con hoặc chết để bảo vệ con.', 'Tiếng trẻ khóc ngặt nghẽo đêm khuya; mùi sữa ôi thiu; nôi tự đuôi đung đưa; máu nhuộm bụng dưới.', 'Nghe trẻ khóc ngoài cửa, chớ mở cửa tìm.', 'Vạn Tử Cung', 'Không gian dạ con khổng lồ nuốt chửng kẻ thù vào làm thai nhi.', 'Huyết Mẫu Quỷ', 'Mẫu Chấp Hệ', 'Hung Sát', 'Máu nuôi thai nhi, oán nuôi ác quỷ.', 'Máu nuôi thai nhi, oán nuôi ác quỷ.', 'Quỷ Mẫu mất đi hoàn toàn lý trí sau khi bị phản bội hoặc bị ép chết cả mẹ lẫn con.', 'Xem mọi sinh vật sống là mối đe doạ, dùng máu và oán khí biến cơ thể thành ổ quỷ.', 'Mọi sinh thể đi vào vực đều bị coi là kẻ thù đến cướp con.', '【Huyết Thai Vực】 — Mọi bề mặt biến thành thịt máu đỏ tươi như trong tử cung.', 'Đoạn dây rốn nối liền hài cốt mẹ và đứa trẻ.', 'Chưa cập nhật', 'Bụng nó càng to, sát khí phát ra càng tàn bạo.'),
(30, 6, 'MẪU CHẤP HỆ', '六 · QUỶ MẪU', 'Mẫu tử là duyên. Duyên đứt mà lòng không đoạn, sinh chấp thành quỷ.', 'Sinh từ người mẹ chết khi mang thai, chết khi sinh, mất con hoặc chết để bảo vệ con.', 'Tiếng trẻ khóc ngặt nghẽo đêm khuya; mùi sữa ôi thiu; nôi tự đuôi đung đưa; máu nhuộm bụng dưới.', 'Nghe trẻ khóc ngoài cửa, chớ mở cửa tìm.', 'Vạn Tử Cung', 'Không gian dạ con khổng lồ nuốt chửng kẻ thù vào làm thai nhi.', 'Quỷ Mẫu', 'Mẫu Chấp Hệ', 'Quỷ Tướng', 'Một tiếng khóc là một đứa trẻ. Một vạn tiếng khóc là một đạo quân.', 'Một tiếng khóc là một đứa trẻ. Một vạn tiếng khóc là một đạo quân.', 'Đạt đến đỉnh cao của Mẫu Chấp Hệ, biến thành Mẹ Của Vạn Quỷ.', 'Có khả năng tự sinh ra các Quỷ Tử từ âm khí và điều khiển chúng như một đạo quân.', 'Quỷ Tử không bao giờ chết hết nếu Quỷ Mẫu còn sống; sinh lực Quỷ Mẫu liên kết với vạn con.', '【Vạn Tử Cung】 — Cung điện quỷ dữ chứa vô số thai nhi bằng âm khí.', 'Trái tim mẫu tử — Nơi cất giữ tình thương cuối cùng bị bóp méo.', 'Chưa cập nhật', 'Khi Quỷ Mẫu cất tiếng ru, vạn quỷ tử dội tiếng khóc làm nát đất trời.'),

-- Volume 7: Ấu Hồn Hệ (Tiểu Quỷ)
(31, 7, 'ẤU HỒN HỆ', '七 · TIỂU QUỶ', 'Trẻ chết không hiểu luân hồi. Chúng chỉ biết mình vẫn còn muốn chơi.', 'Sinh từ trẻ em chết sớm (chết lưu, chết đuối, bị bỏ rơi). Sức mạnh không nằm ở oán khí tàn bạo mà ở quy luật trò chơi quỷ quái.', 'Tiếng cười khúc khắc đêm khuya; dải ruy băng/đồ chơi bỏ lại; vết chân nhỏ bằng máu; đồ đạc bị giấu.', 'Nghe tiếng cười dưới giường, chớ cúi nhìn.', 'Ngoạn Đường', 'Căn phòng chơi đùa nơi mọi trò chơi dân gian biến thành trò chơi sinh tử.', 'Dạ Đề Quỷ', 'Ấu Hồn Hệ', 'Du Hồn', 'Tiếng khóc đêm khuya, dỗ dành là mất mạng.', 'Tiếng khóc đêm khuya, dỗ dành là mất mạng.', 'Sinh ra từ trẻ sơ sinh chết vì bệnh tật, bị bỏ rơi khóc kiệt sức trong đêm lạnh.', 'Phát ra tiếng khóc thảm thiết giữa đêm để dụ lòng tốt của người sống.', 'Ai cất lời dỗ dành hoặc ôm lấy nó → Bị đánh dấu và thu giữ sinh khí.', '【Dạ Khốc Vực】 — Tiếng khóc vang vọng làm màng nhĩ nạn nhân chảy máu.', 'Chiếc nôi gỗ hoặc chiếc tã lót đầu tiên.', 'Chưa cập nhật', 'Nửa đêm đường vắng thấy đứa trẻ khóc một mình, hãy bước đi thật nhanh.'),
(32, 7, 'ẤU HỒN HỆ', '七 · TIỂU QUỶ', 'Trẻ chết không hiểu luân hồi. Chúng chỉ biết mình vẫn còn muốn chơi.', 'Sinh từ trẻ em chết sớm (chết lưu, chết đuối, bị bỏ rơi). Sức mạnh không nằm ở oán khí tàn bạo mà ở quy luật trò chơi quỷ quái.', 'Tiếng cười khúc khắc đêm khuya; dải ruy băng/đồ chơi bỏ lại; vết chân nhỏ bằng máu; đồ đạc bị giấu.', 'Nghe tiếng cười dưới giường, chớ cúi nhìn.', 'Ngoạn Đường', 'Căn phòng chơi đùa nơi mọi trò chơi dân gian biến thành trò chơi sinh tử.', 'Sàng Hạ Quỷ', 'Ấu Hồn Hệ', 'Du Hồn', 'Nó không ở trong tủ, nó ở ngay dưới lưng ngươi.', 'Nó không ở trong tủ, nó ở ngay dưới lưng ngươi.', 'Trẻ em bị trốn chui trốn lủi rồi chết dưới gầm giường do hỏa hoạn hoặc trộm cướp.', 'Ẩn nấp dưới gầm giường, chờ đợi nạn nhân sơ hở.', 'Chỉ phát động tấn công khi nạn nhân tò mò cúi đầu xuống nhìn dưới gầm giường.', '【Sàng Hạ Vực】 — Khoảng trống dưới gầm giường biến thành vực sâu vô tận.', 'Món đồ chơi mà đứa trẻ cầm theo lúc trốn dưới gầm giường.', 'Chưa cập nhật', 'Thấy bóng đen dưới gầm giường, nhắm mắt lại mới giữ được mạng.'),
(33, 7, 'ẤU HỒN HỆ', '七 · TIỂU QUỶ', 'Trẻ chết không hiểu luân hồi. Chúng chỉ biết mình vẫn còn muốn chơi.', 'Sinh từ trẻ em chết sớm (chết lưu, chết đuối, bị bỏ rơi). Sức mạnh không nằm ở oán khí tàn bạo mà ở quy luật trò chơi quỷ quái.', 'Tiếng cười khúc khắc đêm khuya; dải ruy băng/đồ chơi bỏ lại; vết chân nhỏ bằng máu; đồ đạc bị giấu.', 'Nghe tiếng cười dưới giường, chớ cúi nhìn.', 'Ngoạn Đường', 'Căn phòng chơi đùa nơi mọi trò chơi dân gian biến thành trò chơi sinh tử.', 'Ngoan Đồng Quỷ', 'Ấu Hồn Hệ', 'Oán Hồn', 'Chỉ là trò chơi thôi mà... sao ngươi lại chết?', 'Chỉ là trò chơi thôi mà... sao ngươi lại chết?', 'Trẻ em chết khi đang chơi đùa (ngã giếng, chết đuối) nhưng tâm trí vẫn nghĩ mình đang chơi.', 'Nghịch ngợm, giấu đồ, kéo chân, làm đổ vỡ. Không có khái niệm sống chết.', 'Nếu bị người sống chọc giận hoặc từ chối chơi cùng → Chuyển sang dạng sát quỷ tàn sát.', '【Ngoạn Đường Vực】 — Biến không gian xung quanh thành công viên trò chơi đẫm máu.', 'Món đồ chơi yêu thích nhất lúc còn sống.', 'Chưa cập nhật', 'Trẻ con chơi với quỷ, người già khóc trong đêm.'),
(34, 7, 'ẤU HỒN HỆ', '七 · TIỂU QUỶ', 'Trẻ chết không hiểu luân hồi. Chúng chỉ biết mình vẫn còn muốn chơi.', 'Sinh từ trẻ em chết sớm (chết lưu, chết đuối, bị bỏ rơi). Sức mạnh không nằm ở oán khí tàn bạo mà ở quy luật trò chơi quỷ quái.', 'Tiếng cười khúc khắc đêm khuya; dải ruy băng/đồ chơi bỏ lại; vết chân nhỏ bằng máu; đồ đạc bị giấu.', 'Nghe tiếng cười dưới giường, chớ cúi nhìn.', 'Ngoạn Đường', 'Căn phòng chơi đùa nơi mọi trò chơi dân gian biến thành trò chơi sinh tử.', 'Quỷ Đồng Tử', 'Ấu Hồn Hệ', 'Lệ Quỷ', 'Nó có khuôn mặt ngây thơ, nhưng đôi mắt không có tròng đen.', 'Nó có khuôn mặt ngây thơ, nhưng đôi mắt không có tròng đen.', 'Ấu hồn hấp thụ đủ âm khí, mở ra trí tuệ sơ khai, biết giả dạng trẻ em còn sống.', 'Giả làm trẻ lạc để xâm nhập vào các gia đình người sống, ăn dần dương khí gia chủ.', 'Tuyệt đối không được để nó phát hiện ra bạn đã biết "Nó không có bóng".', '【Đồng Giả Vực】 — Tạo ảo giác căn nhà ấm áp nhưng thực chất là hang quỷ.', 'Chiếc vòng đeo cổ bằng bạc hoặc khóa mệnh lúc nhỏ.', 'Chưa cập nhật', 'Đứa trẻ mới nhận nuôi không bao giờ soi chiếu bóng mình dưới ánh nắng.'),
(35, 7, 'ẤU HỒN HỆ', '七 · TIỂU QUỶ', 'Trẻ chết không hiểu luân hồi. Chúng chỉ biết mình vẫn còn muốn chơi.', 'Sinh từ trẻ em chết sớm (chết lưu, chết đuối, bị bỏ rơi). Sức mạnh không nằm ở oán khí tàn bạo mà ở quy luật trò chơi quỷ quái.', 'Tiếng cười khúc khắc đêm khuya; dải ruy băng/đồ chơi bỏ lại; vết chân nhỏ bằng máu; đồ đạc bị giấu.', 'Nghe tiếng cười dưới giường, chớ cúi nhìn.', 'Ngoạn Đường', 'Căn phòng chơi đùa nơi mọi trò chơi dân gian biến thành trò chơi sinh tử.', 'Đồng Sát Quỷ', 'Ấu Hồn Hệ', 'Hung Sát', 'Ngây thơ hòa cùng hung sát, họa tàn khốc nhất gian trần.', 'Ngây thơ hòa cùng hung sát, họa tàn khốc nhất gian trần.', 'Tiểu Quỷ nuốt quá nhiều oán khí, biến dị thành Hung Sát thực thụ.', 'Tàn sát tàn bạo không lý do, lấy việc hành hạ nạn nhân làm niềm vui trẻ con.', 'Khi tiến vào vực, nạn nhân phải tuân theo các quy tắc trò chơi chết chóc của nó.', '【Bách Đồng Vực】 — Hàng trăm bản sao đứa trẻ xuất hiện cười đùa tàn sát.', 'Đứa trẻ bản thể thật sự ẩn giấu trong hàng trăm bản sao.', 'Chưa cập nhật', 'Đừng để tiếng cười của Đồng Sát Quỷ làm ngươi quên mất đao trên tay.'),

-- Volume 8: Oan Ngục Hệ (Tử Lao Quỷ)
(36, 8, 'OAN NGỤC HỆ', '八 · TỬ LAO QUỶ', 'Xiềng khóa thân, hình khóa hồn.', 'Sinh ra từ nhà ngục cổ, ngục tối, nơi oan khuất không được giải thích, tù nhân chết rục.', 'Tiếng xích sắt kéo lê trên đá; tiếng van xin oan uổng; mùi mốc meo và rơm rạ mục; gông cuồng tự hiện.', 'Nghe xiềng kéo phía sau, chớ quay đầu.', 'Vạn Ngục', 'Biến mọi căn phòng thành gian phòng giam u tối không lối thoát.', 'Ngục Quỷ', 'Oan Ngục Hệ', 'Du Hồn', 'Vào ngục dễ, ra ngục khó.', 'Vào ngục dễ, ra ngục khó.', 'Oán khí của hàng trăm tù nhân chết rục trong một phòng giam chật hẹp kết tụ lại.', 'Cố định tại một không gian giam giữ, biến không gian đó thành nhà ngục vĩnh cửu.', 'Bất kỳ ai bước chân vào phòng giam sẽ không bao giờ tìm thấy cửa ra nữa.', '【Tử Ngục Vực】 — Bức tường đá dày đặc ngăn cách hoàn toàn với thế giới thực.', 'Chiếc chìa khóa ngục bằng đồng gỉ sét.', 'Chưa cập nhật', 'Có những gian phòng hoang vốn dĩ là một nhà ngục chưa bao giờ đóng cửa.'),
(37, 8, 'OAN NGỤC HỆ', '八 · TỬ LAO QUỶ', 'Xiềng khóa thân, hình khóa hồn.', 'Sinh ra từ nhà ngục cổ, ngục tối, nơi oan khuất không được giải thích, tù nhân chết rục.', 'Tiếng xích sắt kéo lê trên đá; tiếng van xin oan uổng; mùi mốc meo và rơm rạ mục; gông cuồng tự hiện.', 'Nghe xiềng kéo phía sau, chớ quay đầu.', 'Vạn Ngục', 'Biến mọi căn phòng thành gian phòng giam u tối không lối thoát.', 'Tỏa Hồn Quỷ', 'Oan Ngục Hệ', 'Oán Hồn', 'Trầm xích khóa linh hồn, giãy giụa chỉ thêm đau.', 'Trầm xích khóa linh hồn, giãy giụa chỉ thêm đau.', 'Phạm nhân bị xích bằng gông sắt cho đến chết, oán khí nhập vào xiềng xích.', 'Phóng xích sắt từ bóng tối để trói chặt linh hồn nạn nhân.', 'Nạn nhân càng dùng sức giãy giụa, xiềng xích càng siết chặt và đâm sâu vào hồn thể.', '【Tỏa Hồn Vực】 — Hàng vạn sợi dây xích sắt giăng kín không gian.', 'Ổ khóa sắt lớn nằm ngay trên ngực quỷ.', 'Chưa cập nhật', 'Tiếng xích va vào nhau trong đêm là lời báo hiệu hồn ngươi sắp bị khóa.'),
(38, 8, 'OAN NGỤC HỆ', '八 · TỬ LAO QUỶ', 'Xiềng khóa thân, hình khóa hồn.', 'Sinh ra từ nhà ngục cổ, ngục tối, nơi oan khuất không được giải thích, tù nhân chết rục.', 'Tiếng xích sắt kéo lê trên đá; tiếng van xin oan uổng; mùi mốc meo và rơm rạ mục; gông cuồng tự hiện.', 'Nghe xiềng kéo phía sau, chớ quay đầu.', 'Vạn Ngục', 'Biến mọi căn phòng thành gian phòng giam u tối không lối thoát.', 'Hình Quỷ', 'Oan Ngục Hệ', 'Lệ Quỷ', 'Kẹp ngón tay, xẻng thịt, đóng đinh... ngươi muốn thử cái nào?', 'Kẹp ngón tay, xẻng thịt, đóng đinh... ngươi muốn thử cái nào?', 'Tích tụ từ những đòn tra tấn dã man trong ngục tối khiến tù nhân chết trong đau đớn tột cùng.', 'Tái hiện các hình phạt tra tấn cổ xưa lên cơ thể nạn nhân.', 'Nạn nhân bước vào vực bắt buộc phải chịu đựng một trong các loại dụng cụ tra tấn.', '【Bách Hình Vực】 — Căn phòng ngập tràn đĩa tra tấn, kìm kẹp, đinh sắt và đao phủ.', 'Bộ dụng cụ tra tấn đầu tiên gây ra cái chết của tù nhân.', 'Chưa cập nhật', 'Vết thương do Hình Quỷ gây ra không bao giờ khép miệng.'),
(39, 8, 'OAN NGỤC HỆ', '八 · TỬ LAO QUỶ', 'Xiềng khóa thân, hình khóa hồn.', 'Sinh ra từ nhà ngục cổ, ngục tối, nơi oan khuất không được giải thích, tù nhân chết rục.', 'Tiếng xích sắt kéo lê trên đá; tiếng van xin oan uổng; mùi mốc meo và rơm rạ mục; gông cuồng tự hiện.', 'Nghe xiềng kéo phía sau, chớ quay đầu.', 'Vạn Ngục', 'Biến mọi căn phòng thành gian phòng giam u tối không lối thoát.', 'Ngục Tốt Quỷ', 'Oan Ngục Hệ', 'Hung Sát', 'Trong ngục của ta, lời ta là luật!', 'Trong ngục của ta, lời ta là luật!', 'Cai ngục tàn bạo chết trong ngục hoặc oán khí biến cai ngục thành kẻ canh giữ vĩnh cửu.', 'Có trí tuệ cao, đi lại tuần tra và cưỡng ép mọi sinh linh phải tuân theo "Ngục Quy".', 'Vi phạm bất kỳ quy tắc nào do Ngục Tốt đề ra (không được nói, không được chạy) → Bị xử tử ngay.', '【Tần Ngục Vực】 — Không gian ngục tối có quy tắc tuyệt đối nghiêm ngặt.', 'Sổ Bạ Tù Nhân mà Ngục Tốt cầm trên tay.', 'Chưa cập nhật', 'Kẻ cai quản nhà ngục ma quỷ còn tàn bạo hơn cả quỷ dữ.'),
(40, 8, 'OAN NGỤC HỆ', '八 · TỬ LAO QUỶ', 'Xiềng khóa thân, hình khóa hồn.', 'Sinh ra từ nhà ngục cổ, ngục tối, nơi oan khuất không được giải thích, tù nhân chết rục.', 'Tiếng xích sắt kéo lê trên đá; tiếng van xin oan uổng; mùi mốc meo và rơm rạ mục; gông cuồng tự hiện.', 'Nghe xiềng kéo phía sau, chớ quay đầu.', 'Vạn Ngục', 'Biến mọi căn phòng thành gian phòng giam u tối không lối thoát.', 'Oan Ngục Quỷ', 'Oan Ngục Hệ', 'Quỷ Tướng', 'Oan này không thấu trời xanh, bắt người sống chịu thay.', 'Oan này không thấu trời xanh, bắt người sống chịu thay.', 'Đạt cấp Hung Sát / Quỷ Tướng từ những án oan thảm khốc diệt tộc thời xưa.', 'Khởi động quy luật "Chịu Án Thay", ép người sống phải gánh chịu toàn bộ nỗi đau án oan.', 'Không cần ra tay trực tiếp, nạn nhân sẽ tự gánh chịu các vết thương án oan trong lịch sử.', '【Vạn Ngục Vực】 — Đại không gian ngục tối nuốt trọn cả một vùng đất.', 'Bằng chứng hoặc cuộn sớ chứng minh vụ án oan năm xưa.', 'Chưa cập nhật', 'Khi án oan được giải, Vạn Ngục tự sụp đổ.'),

-- Volume 9: Chiến Tử Hệ (Binh Hồn)
(41, 9, 'CHIẾN TỬ HỆ', '九 · BINH HỒN', 'Quân chết ngoài trận, hồn không biết chiến tranh đã kết thúc.', 'Sinh ra từ chiến trường cổ, gò chôn vạn dân, nơi diễn ra các trận đại chiến tàn khốc.', 'Tiếng ngựa hú, tiếng va chạm binh khí; cờ trận rách rưới bay trong sương; mùi thuốc súng và máu khô.', 'Âm binh qua đường, chớ đứng giữa hàng.', 'Âm Quân', 'Biến không gian thành bãi chiến trường cổ đẫm máu.', 'Âm Binh', 'Chiến Tử Hệ', 'Du Hồn', 'Tiếng bước chân rầm rộ, hàng ngũ chỉnh tề... nhưng họ đã chết nghìn năm.', 'Tiếng bước chân rầm rộ, hàng ngũ chỉnh tề... nhưng họ đã chết nghìn năm.', 'Hàng vạn binh sĩ tử trận cùng lúc trên chiến trường, hồn không hay biết mình đã chết.', 'Hành quân theo đội hình chỉnh tề, nghiền nát bất kỳ vật cản nào trên đường đi.', 'Người sống đứng ngáng đường hoặc đứng giữa hàng ngũ âm binh → Bị xéo nát sinh hồn.', '【Âm Quân Vực】 — Sương mù quân sự bao phủ, tiếng trống trận vang trời.', 'Lá cờ lệnh (Quân Kỳ) của đạo quân.', 'Chưa cập nhật', 'Âm Binh mượn đường, người sống tránh bên.'),
(42, 9, 'CHIẾN TỬ HỆ', '九 · BINH HỒN', 'Quân chết ngoài trận, hồn không biết chiến tranh đã kết thúc.', 'Sinh ra từ chiến trường cổ, gò chôn vạn dân, nơi diễn ra các trận đại chiến tàn khốc.', 'Tiếng ngựa hú, tiếng va chạm binh khí; cờ trận rách rưới bay trong sương; mùi thuốc súng và máu khô.', 'Âm binh qua đường, chớ đứng giữa hàng.', 'Âm Quân', 'Biến không gian thành bãi chiến trường cổ đẫm máu.', 'Vô Đầu Binh', 'Chiến Tử Hệ', 'Oán Hồn', 'Không mắt để nhìn, không tai để nghe, chỉ có sát niệm chém giết.', 'Không mắt để nhìn, không tai để nghe, chỉ có sát niệm chém giết.', 'Binh sĩ bị chém đứt đầu trên chiến trường, oán khí đọng lại trong thân thể mất đầu.', 'Mất khả năng phân biệt đồng minh hay kẻ thù, vung đao chém loạn điên cuồng.', 'Đi tìm những sinh linh "mang đầu" để chém rớt đầu họ thay thế.', '【Trảm Đầu Vực】 — Không gian tràn ngập đao quang kiếm ảnh không mục đích.', 'Cái đầu bị đứt đang bị vùi lấp gần đó.', 'Chưa cập nhật', 'Tiếng đao xé gió giữa đêm hoang là của những chiến sĩ vô đầu.'),
(43, 9, 'CHIẾN TỬ HỆ', '九 · BINH HỒN', 'Quân chết ngoài trận, hồn không biết chiến tranh đã kết thúc.', 'Sinh ra từ chiến trường cổ, gò chôn vạn dân, nơi diễn ra các trận đại chiến tàn khốc.', 'Tiếng ngựa hú, tiếng va chạm binh khí; cờ trận rách rưới bay trong sương; mùi thuốc súng và máu khô.', 'Âm binh qua đường, chớ đứng giữa hàng.', 'Âm Quân', 'Biến không gian thành bãi chiến trường cổ đẫm máu.', 'Kỵ Quỷ', 'Chiến Tử Hệ', 'Lệ Quỷ', 'Tiếng vó ngựa dồn dập, gươm sáng xé màn đêm.', 'Tiếng vó ngựa dồn dập, gươm sáng xé màn đêm.', 'Kỵ binh cùng chiến mã đồng loạt tử trận trong các đợt càn quét.', 'Di chuyển với tốc độ cực cao, cưỡi chiến mã tạo bằng âm khí càn quét kẻ thù.', 'Khi Kỵ Quỷ tích đủ đà phi ngựa, đòn tấn công sở hữu sức mạnh xuyên phá tuyệt đối.', '【Thiết Kỵ Vực】 — Mặt đất rung chuyển như có vạn ngựa dẫm đạp.', 'Bộ móng ngựa hoặc chiếc yên ngựa gốc.', 'Chưa cập nhật', 'Chiến mã ma quỷ không cần cỏ tươi, nó ăn bằng sinh khí kẻ thù.'),
(44, 9, 'CHIẾN TỬ HỆ', '九 · BINH HỒN', 'Quân chết ngoài trận, hồn không biết chiến tranh đã kết thúc.', 'Sinh ra từ chiến trường cổ, gò chôn vạn dân, nơi diễn ra các trận đại chiến tàn khốc.', 'Tiếng ngựa hú, tiếng va chạm binh khí; cờ trận rách rưới bay trong sương; mùi thuốc súng và máu khô.', 'Âm binh qua đường, chớ đứng giữa hàng.', 'Âm Quân', 'Biến không gian thành bãi chiến trường cổ đẫm máu.', 'Đao Binh Quỷ', 'Chiến Tử Hệ', 'Hung Sát', 'Đao không nỡ rời tay, người chết đao vẫn chém.', 'Đao không nỡ rời tay, người chết đao vẫn chém.', 'Binh sĩ chết nhưng tay vẫn nắm chặt vũ khí, oán khí dồn hết vào thanh binh khí.', 'Binh khí tự phát ra đao khí sắc bén; thân thể quỷ có thể nát nhưng đao không gãy.', 'Mọi sinh thể tiến vào phạm vi chém của đao đều bị phân thành hàng trăm mảnh.', '【Đao Môn Vực】 — Vực không gian sắc bén như ngàn lưỡi đao vây hãm.', 'Thanh đao/bản thể vũ khí gốc.', 'Chưa cập nhật', 'Thanh đao rỉ sét dưới đất cổ đôi khi chứa đựng oán khí của vạn người.'),
(45, 9, 'CHIẾN TỬ HỆ', '九 · BINH HỒN', 'Quân chết ngoài trận, hồn không biết chiến tranh đã kết thúc.', 'Sinh ra từ chiến trường cổ, gò chôn vạn dân, nơi diễn ra các trận đại chiến tàn khốc.', 'Tiếng ngựa hú, tiếng va chạm binh khí; cờ trận rách rưới bay trong sương; mùi thuốc súng và máu khô.', 'Âm binh qua đường, chớ đứng giữa hàng.', 'Âm Quân', 'Biến không gian thành bãi chiến trường cổ đẫm máu.', 'Quỷ Tướng', 'Chiến Tử Hệ', 'Quỷ Tướng', 'Một Quỷ Tướng không đáng sợ bằng một Quỷ Tướng biết đánh trận.', 'Một Quỷ Tướng không đáng sợ bằng một Quỷ Tướng biết đánh trận.', 'Danh tướng tử trận mang theo uất hận mất nước hoặc bị hãm hại, thống lĩnh vạn âm binh.', 'Trí tuệ cực cao, biết bày binh bố trận, mai phục, dụ địch và dùng chiến thuật tàn bạo.', 'Điều khiển và chia sẻ sức mạnh với toàn bộ quân sĩ dưới quyền.', '【Vạn Quân Vực】 — Bản đồ bãi chiến trường hoàn chỉnh với hàng vạn âm binh túc trực.', 'Chân Linh Ấn/Ấn Báo Lệnh của Quỷ Tướng.', 'Chưa cập nhật', 'Khi Quỷ Tướng rút gươm, cả bãi chiến trường cổ như sống lại.'),

-- Volume 10: Vai Diễn Hệ (Hí Quỷ)
(46, 10, 'VAI DIỄN HỆ', '十 · HÍ QUỶ', 'Sân khấu mở, vai đã định. Người bước lên đài, sinh tử thành kịch.', 'Sinh ra từ rạp hát cổ, gánh hát ma, đào kép chết thảm trên sân khấu, mặt nạ gốm cổ.', 'Tiếng đàn nhị vang vọng; tiếng hát tuồng não nuột; mặt nạ tự đổi sắc thái; rèm nhung đỏ rung rinh.', 'Vở diễn chưa hết, chớ rời sân khấu.', 'Bách Hí Thành', 'Cả vùng đất biến thành một sân khấu kịch khổng lồ.', 'Xướng Hồn', 'Vai Diễn Hệ', 'Du Hồn', 'Tiếng hát cất lên, hồn lìa khỏi xác.', 'Tiếng hát cất lên, hồn lìa khỏi xác.', 'Đào kép nổi tiếng chết oan hoặc bị hạ độc ngay trên sân khấu lúc đang hát.', 'Dùng tiếng hát u buồn, ma mị để mê hoặc và dẫn dụ sinh hồn nạn nhân rời khỏi xác.', 'Nghe trọn vẹn một đoạn hát mà không phá giải → Sinh hồn tự động tách khỏi xác.', '【Xướng Đài Vực】 — Rạp hát cổ lung linh ánh đèn nhưng ngập tràn âm khí.', 'Chiếc quạt xòe hoặc bộ trang phục diễn xuất gốc.', 'Chưa cập nhật', 'Đêm tối nghe tiếng hát tuồng trong đền hoang, hãy bịt chặt tai lại.'),
(47, 10, 'VAI DIỄN HỆ', '十 · HÍ QUỶ', 'Sân khấu mở, vai đã định. Người bước lên đài, sinh tử thành kịch.', 'Sinh ra từ rạp hát cổ, gánh hát ma, đào kép chết thảm trên sân khấu, mặt nạ gốm cổ.', 'Tiếng đàn nhị vang vọng; tiếng hát tuồng não nuột; mặt nạ tự đổi sắc thái; rèm nhung đỏ rung rinh.', 'Vở diễn chưa hết, chớ rời sân khấu.', 'Bách Hí Thành', 'Cả vùng đất biến thành một sân khấu kịch khổng lồ.', 'Diện Quỷ', 'Vai Diễn Hệ', 'Oán Hồn', 'Đeo mặt nạ vào, ngươi không còn là chính ngươi.', 'Đeo mặt nạ vào, ngươi không còn là chính ngươi.', 'Những chiếc mặt nạ tuồng cổ hấp thụ âm khí qua hàng trăm vở diễn thảm kịch.', 'Bám vào mặt người sống, cưỡng ép nạn nhân phải đóng đúng vai diễn của chiếc mặt nạ.', 'Không được tháo mặt nạ ra trước khi kịch bản kịch kết thúc; gỡ ra mặt sẽ bị lột theo.', '【Diện Phổ Vực】 — Hàng ngàn chiếc mặt nạ bay lượn trên không trung.', 'Chiếc mặt nạ nguyên bản đầu tiên chưa tô màu.', 'Chưa cập nhật', 'Đừng bao giờ thử đeo những chiếc mặt nạ gỗ cũ kỹ nhặt được ngoài đường.'),
(48, 10, 'VAI DIỄN HỆ', '十 · HÍ QUỶ', 'Sân khấu mở, vai đã định. Người bước lên đài, sinh tử thành kịch.', 'Sinh ra từ rạp hát cổ, gánh hát ma, đào kép chết thảm trên sân khấu, mặt nạ gốm cổ.', 'Tiếng đàn nhị vang vọng; tiếng hát tuồng não nuột; mặt nạ tự đổi sắc thái; rèm nhung đỏ rung rinh.', 'Vở diễn chưa hết, chớ rời sân khấu.', 'Bách Hí Thành', 'Cả vùng đất biến thành một sân khấu kịch khổng lồ.', 'Khôi Lỗi Quỷ', 'Vai Diễn Hệ', 'Lệ Quỷ', 'Dây kéo trên đầu, ngươi chỉ là con rối.', 'Dây kéo trên đầu, ngươi chỉ là con rối.', 'Nghệ nhân rối bóng/rối dây chết cùng gánh rối, hoặc vong hồn bị giật dây như con rối.', 'Bắn ra các sợi dây âm khí trong suốt để điều khiển cơ thể người sống làm trò vui.', 'Người bị giật dây hoàn toàn mất kiểm soát cơ thể dù tâm trí vẫn tỉnh táo.', '【Khôi Lỗi Đài】 — Sân khấu với hàng vạn sợi dây tơ rủ xuống từ hư không.', 'Sợi dây điều khiển trung tâm nối vào ngón tay quỷ.', 'Chưa cập nhật', 'Khi khớp xương ngươi tự di chuyển, ngươi đã trở thành con rối của nó.'),
(49, 10, 'VAI DIỄN HỆ', '十 · HÍ QUỶ', 'Sân khấu mở, vai đã định. Người bước lên đài, sinh tử thành kịch.', 'Sinh ra từ rạp hát cổ, gánh hát ma, đào kép chết thảm trên sân khấu, mặt nạ gốm cổ.', 'Tiếng đàn nhị vang vọng; tiếng hát tuồng não nuột; mặt nạ tự đổi sắc thái; rèm nhung đỏ rung rinh.', 'Vở diễn chưa hết, chớ rời sân khấu.', 'Bách Hí Thành', 'Cả vùng đất biến thành một sân khấu kịch khổng lồ.', 'Hí Sát', 'Vai Diễn Hệ', 'Hung Sát', 'Kịch bản đã viết ngươi phải chết, ngươi không thể sống.', 'Kịch bản đã viết ngươi phải chết, ngươi không thể sống.', 'Vở kịch chết chóc được dàn dựng từ một vụ thảm sát gánh hát trong quá khứ.', 'Biến toàn bộ không gian xung quanh thành vở kịch. Người tham gia bị phân vai chết.', 'Nhân vật trong kịch chết thế nào (bị hạ độc, chém đầu) → Nạn nhân ngoài đời chết đúng như vậy.', '【Hí Sát Vực】 — Toàn bộ đạo cụ trên sân khấu đều trở thành hung khí thật.', 'Cuộn kịch bản gốc ghi bằng mực tàu.', 'Chưa cập nhật', 'Trong vở kịch của Hí Sát, không có diễn viên nào sống sót đến hạ màn.'),
(50, 10, 'VAI DIỄN HỆ', '十 · HÍ QUỶ', 'Sân khấu mở, vai đã định. Người bước lên đài, sinh tử thành kịch.', 'Sinh ra từ rạp hát cổ, gánh hát ma, đào kép chết thảm trên sân khấu, mặt nạ gốm cổ.', 'Tiếng đàn nhị vang vọng; tiếng hát tuồng não nuột; mặt nạ tự đổi sắc thái; rèm nhung đỏ rung rinh.', 'Vở diễn chưa hết, chớ rời sân khấu.', 'Bách Hí Thành', 'Cả vùng đất biến thành một sân khấu kịch khổng lồ.', 'Bách Hí Quỷ', 'Vai Diễn Hệ', 'Quỷ Tướng', 'Không có vai chính. Chỉ có người chưa biết mình sẽ chết ở màn nào.', 'Không có vai chính. Chỉ có người chưa biết mình sẽ chết ở màn nào.', 'Đại thành của Hí Hệ, hấp thu vạn vở thảm kịch và hàng ngàn sinh hồn nghệ sĩ.', 'Có khả năng đồng thời diễn hàng trăm vở kịch khác nhau, thao túng vạn người cùng lúc.', 'Mọi sinh linh trong phạm vi vực đều bị bắt buộc trở thành khán giả hoặc diễn viên.', '【Bách Hí Thành】 — Cả thành phố biến thành rạp hát khổng lồ vô tận.', 'Sân khấu trung tâm nguyên bản nơi vở kịch đầu tiên diễn ra.', 'Chưa cập nhật', 'Hạ màn rồi, nhưng người diễn đã không còn thở nữa.'),

-- Volume 11: Tử Thi Hệ (Thi Quỷ)
(51, 11, 'TỬ THI HỆ', '十一 · THI QUỶ', 'Xác chết vốn vô tri. Có thứ khiến nó đứng dậy, ấy là Thi Quỷ.', 'Sinh ra từ thi thể hấp thụ âm khí, địa khí xấu, phong thủy tụ âm hoặc bị ma nhập xác.', 'Mùi tử khí thối vữa; đất xung quanh bị khô cằn/mốc đen; tiếng móng tay cào quan tài.', 'Thấy xác mở mắt, chớ gọi tên.', 'Hạn Thiên', 'Không gian nóng rát, khô cằn, đống thi thể sống dậy.', 'Bạch Cương', 'Tử Thi Hệ', 'Du Hồn', 'Thịt mềm lông trắng, mới dậy khỏi mồ.', 'Thịt mềm lông trắng, mới dậy khỏi mồ.', 'Thi thể mới chôn nảy sinh biến đổi do tiếp xúc với âm khí hoặc mèo nhảy qua xác.', 'Cơ thể cứng đờ, di chuyển chậm chạp, nhảy từng bước, thịt bắt đầu mọc lông trắng.', 'Nhạy cảm với hơi thở (dương khí) của người sống. Bị thu hút bởi tiếng thở.', '【Thi Âm Vực】 — Căn phòng tràn ngập khói mù ma quái và mùi hôi tử khí.', 'Điểm giữa hai lông mày (Huyệt Ấn Đường).', 'Chưa cập nhật', 'Thấy xác mọc lông trắng trong quan tài, hãy mang vôi bột rải lên ngay.'),
(52, 11, 'TỬ THI HỆ', '十一 · THI QUỶ', 'Xác chết vốn vô tri. Có thứ khiến nó đứng dậy, ấy là Thi Quỷ.', 'Sinh ra từ thi thể hấp thụ âm khí, địa khí xấu, phong thủy tụ âm hoặc bị ma nhập xác.', 'Mùi tử khí thối vữa; đất xung quanh bị khô cằn/mốc đen; tiếng móng tay cào quan tài.', 'Thấy xác mở mắt, chớ gọi tên.', 'Hạn Thiên', 'Không gian nóng rát, khô cằn, đống thi thể sống dậy.', 'Hắc Cương', 'Tử Thi Hệ', 'Oán Hồn', 'Da đen như sắt, móng sắc như đao.', 'Da đen như sắt, móng sắc như đao.', 'Bạch Cương hấp thụ đủ âm khí qua nhiều năm, lông trắng rụng đi, da chuyển màu đen sẫm.', 'Da thịt cứng như đá sắt, móng tay mang kịch độc tử khí, tốc độ di chuyển nhanh hơn.', 'Hút sinh khí trực tiếp bằng cách cắn vào cổ nạn nhân.', '【Hắc Thi Vực】 — Bụi đen tử khí làm mục rữa da thịt người sống khi hít phải.', 'Đỉnh đầu (Huyệt Bách Hội).', 'Chưa cập nhật', 'Đao kiếm thông thường chém vào Hắc Cương chỉ phát ra tiếng chan chát.'),
(53, 11, 'TỬ THI HỆ', '十一 · THI QUỶ', 'Xác chết vốn vô tri. Có thứ khiến nó đứng dậy, ấy là Thi Quỷ.', 'Sinh ra từ thi thể hấp thụ âm khí, địa khí xấu, phong thủy tụ âm hoặc bị ma nhập xác.', 'Mùi tử khí thối vữa; đất xung quanh bị khô cằn/mốc đen; tiếng móng tay cào quan tài.', 'Thấy xác mở mắt, chớ gọi tên.', 'Hạn Thiên', 'Không gian nóng rát, khô cằn, đống thi thể sống dậy.', 'Mao Cương', 'Tử Thi Hệ', 'Lệ Quỷ', 'Thân mọc lông dầy, trèo tường vượt mái.', 'Thân mọc lông dầy, trèo tường vượt mái.', 'Cương thi tu luyện lâu năm, toàn thân mọc lớp lông dài màu xám hoặc nâu đen.', 'Sức mạnh kinh người, có khả năng nhảy cao vượt qua mái nhà, hoạt động linh hoạt như thú dữ.', 'Săn bắt mọi sinh vật có máu nóng trong vùng.', '【Trọng Thi Vực】 — Áp lực âm khí khiến người sống khó di chuyển.', 'Sống lưng (Huyệt Mệnh Môn).', 'Chưa cập nhật', 'Nó trèo lên mái nhà chực chờ người sống mở cửa là nhảy xuống xé xác.'),
(54, 11, 'TỬ THI HỆ', '十一 · THI QUỶ', 'Xác chết vốn vô tri. Có thứ khiến nó đứng dậy, ấy là Thi Quỷ.', 'Sinh ra từ thi thể hấp thụ âm khí, địa khí xấu, phong thủy tụ âm hoặc bị ma nhập xác.', 'Mùi tử khí thối vữa; đất xung quanh bị khô cằn/mốc đen; tiếng móng tay cào quan tài.', 'Thấy xác mở mắt, chớ gọi tên.', 'Hạn Thiên', 'Không gian nóng rát, khô cằn, đống thi thể sống dậy.', 'Phi Cương', 'Tử Thi Hệ', 'Hung Sát', 'Bay trên không trung, trí tuệ như người.', 'Bay trên không trung, trí tuệ như người.', 'Mao Cương tiến hóa vượt bậc, mở ra trí tuệ sơ khai, có khả năng bay lượn trên không.', 'Biết biến hóa, dùng mưu mẹo điều khiển các cương thi cấp thấp làm tay sai (Thi Triều).', 'Có thể điều khiển hàng loạt tử thi trong vùng tự đứng dậy.', '【Thi Triều Vực】 — Hàng vạn tử thi từ các ngôi mộ tự đào đất chui lên.', 'Trái tim cương thi (Thi Hạch).', 'Chưa cập nhật', 'Khi Phi Cương xuất hiện, cả nghĩa trang không còn một ngôi mộ nào yên ổn.'),
(55, 11, 'TỬ THI HỆ', '十一 · THI QUỶ', 'Xác chết vốn vô tri. Có thứ khiến nó đứng dậy, ấy là Thi Quỷ.', 'Sinh ra từ thi thể hấp thụ âm khí, địa khí xấu, phong thủy tụ âm hoặc bị ma nhập xác.', 'Mùi tử khí thối vữa; đất xung quanh bị khô cằn/mốc đen; tiếng móng tay cào quan tài.', 'Thấy xác mở mắt, chớ gọi tên.', 'Hạn Thiên', 'Không gian nóng rát, khô cằn, đống thi thể sống dậy.', 'Hạn Bạt', 'Tử Thi Hệ', 'Quỷ Vương', 'Bạt xuất, thủy tận. Đi đến đâu, đất nứt đến đó.', 'Bạt xuất, thủy tận. Đi đến đâu, đất nứt đến đó.', 'Đỉnh cao của Thi Hệ, biến thành thần tai họa, đi đến đâu gây ra hạn hán đến đó.', 'Thân thể tỏa ra nhiệt độ khủng khiếp làm khô cằn sông hồ, nứt nẻ đất đai, thiêu rụi cây cối.', 'Mặt đất trong phạm vi hàng trăm dặm đều biến thành hoang mạc chết.', '【Hạn Thiên Vực】 — Không gian rực lửa âm hỏa, nước bốc hơi trong chớp mắt.', 'Thi Hạch Tối Tụ nằm sâu trong lồng ngực.', 'Chưa cập nhật', 'Hạn Bạt xuất thế, vạn dặm khô tàn, trăm họ lầm than.'),

-- Volume 12: Cố Địa Hệ (Trạch Quỷ)
(56, 12, 'CỐ ĐỊA HỆ', '十二 · TRẠCH QUỶ', 'Nhà có chủ, đất có linh. Chủ chết không đi, nhà hóa thành mộ.', 'Ký sinh vào nhà cổ, hung trạch, giếng hoang, bếp lửa, giường ngủ cũ.', 'Đồ đạc tự dịch chuyển; tiếng gọi tên trong nhà trống; cầu thang dài thêm; cửa tự khóa.', 'Nhà không người mà có tiếng gọi, chớ đáp.', 'Hung Trạch', 'Căn nhà biến thành một sinh vật sống đầy cạm bẫy.', 'Môn Quỷ', 'Cố Địa Hệ', 'Du Hồn', 'Bước qua cánh cửa này, sinh tử không do ngươi.', 'Bước qua cánh cửa này, sinh tử không do ngươi.', 'Vong linh người gác cửa chết oan hoặc chấp niệm bảo vệ cánh cửa gia tộc.', 'Ký sinh vào cánh cửa chính hoặc cổng làng, kiểm soát toàn bộ người ra vào.', 'Mọi sinh linh bước qua cửa đều phải "xin phép"; nếu không sẽ bị kẹp chết hoặc nuốt hồn.', '【Môn Quan Vực】 — Cánh cửa biến thành một cái miệng khổng lồ đầy răng nhọn.', 'Vòng gõ cửa bằng đồng hoặc tấm biển tên treo trên cửa.', 'Chưa cập nhật', 'Đêm khuya nghe tiếng gõ cửa ba lần, đừng dại dỗ mở cửa.'),
(57, 12, 'CỐ ĐỊA HỆ', '十二 · TRẠCH QUỶ', 'Nhà có chủ, đất có linh. Chủ chết không đi, nhà hóa thành mộ.', 'Ký sinh vào nhà cổ, hung trạch, giếng hoang, bếp lửa, giường ngủ cũ.', 'Đồ đạc tự dịch chuyển; tiếng gọi tên trong nhà trống; cầu thang dài thêm; cửa tự khóa.', 'Nhà không người mà có tiếng gọi, chớ đáp.', 'Hung Trạch', 'Căn nhà biến thành một sinh vật sống đầy cạm bẫy.', 'Táo Quỷ', 'Cố Địa Hệ', 'Oán Hồn', 'Lửa bếp cháy đen, nấu cả thịt người.', 'Lửa bếp cháy đen, nấu cả thịt người.', 'Oán khí tích tụ tại bếp lửa gia đình bị thảm sát hoặc người chết cháy trong bếp.', 'Thao túng lửa bếp, làm thức ăn biến chất thành chất độc, gây hỏa hoạn bất ngờ.', 'Càng nhóm lửa trong gian bếp, Táo Quỷ càng trở nên mạnh mẽ.', '【Hỏa Bếp Vực】 — Căn bếp biến thành lò nung khổng lồ nuốt chửng nạn nhân.', 'Tượng hoặc bài vị Táo Quân cũ bị vắt uế.', 'Chưa cập nhật', 'Khói bếp màu đen bốc lên giữa đêm là điềm Táo Quỷ thức giấc.'),
(58, 12, 'CỐ ĐỊA HỆ', '十二 · TRẠCH QUỶ', 'Nhà có chủ, đất có linh. Chủ chết không đi, nhà hóa thành mộ.', 'Ký sinh vào nhà cổ, hung trạch, giếng hoang, bếp lửa, giường ngủ cũ.', 'Đồ đạc tự dịch chuyển; tiếng gọi tên trong nhà trống; cầu thang dài thêm; cửa tự khóa.', 'Nhà không người mà có tiếng gọi, chớ đáp.', 'Hung Trạch', 'Căn nhà biến thành một sinh vật sống đầy cạm bẫy.', 'Sàng Quỷ', 'Cố Địa Hệ', 'Lệ Quỷ', 'Ngủ trên chiếc giường này, giấc ngủ là vĩnh hằng.', 'Ngủ trên chiếc giường này, giấc ngủ là vĩnh hằng.', 'Người chết trên chiếc giường gỗ cũ do bị sát hại hoặc ốm đau liệt giường lâu năm.', 'Gây ra ảo giác bóng đè, kéo chân nạn nhân xuống đất, hút sinh khí khi ngủ.', 'Tấn công trực tiếp những ai nằm ngủ trên chiếc giường ký sinh của nó.', '【Sàng Mộng Vực】 — Chiếc giường biến thành một chiếc quan tài gỗ khóa chặt nạn nhân.', 'Bốn chân của chiếc giường gỗ cổ.', 'Chưa cập nhật', 'Mua giường cũ phải cẩn thận kẻo mang cả chủ cũ về ngủ chung.'),
(59, 12, 'CỐ ĐỊA HỆ', '十二 · TRẠCH QUỶ', 'Nhà có chủ, đất có linh. Chủ chết không đi, nhà hóa thành mộ.', 'Ký sinh vào nhà cổ, hung trạch, giếng hoang, bếp lửa, giường ngủ cũ.', 'Đồ đạc tự dịch chuyển; tiếng gọi tên trong nhà trống; cầu thang dài thêm; cửa tự khóa.', 'Nhà không người mà có tiếng gọi, chớ đáp.', 'Hung Trạch', 'Căn nhà biến thành một sinh vật sống đầy cạm bẫy.', 'Gia Quỷ', 'Cố Địa Hệ', 'Hung Sát', 'Đây là nhà của ta, cút ra ngoài!', 'Đây là nhà của ta, cút ra ngoài!', 'Vong linh chủ cũ của căn nhà chết nhưng không chịu đi vì chấp niệm tài sản, nhà cửa.', 'Liên tục quấy phá, tạo ra tiếng động, hù dọa để đuổi người chủ mới đi.', 'Người ở mới càng cố tình ngụ lại, mức độ tấn công tàn bạo của quỷ càng tăng.', '【Cố Gia Vực】 — Căn nhà tự tái sinh lại khung cảnh lúc chủ cũ còn sống.', 'Tờ văn tự mua bán nhà hoặc di chúc cũ bị giấu.', 'Chưa cập nhật', 'Nhà rẻ bất thường thường có một chủ nhân âm thế chưa chịu dời đi.'),
(60, 12, 'CỐ ĐỊA HỆ', '十二 · TRẠCH QUỶ', 'Nhà có chủ, đất có linh. Chủ chết không đi, nhà hóa thành mộ.', 'Ký sinh vào nhà cổ, hung trạch, giếng hoang, bếp lửa, giường ngủ cũ.', 'Đồ đạc tự dịch chuyển; tiếng gọi tên trong nhà trống; cầu thang dài thêm; cửa tự khóa.', 'Nhà không người mà có tiếng gọi, chớ đáp.', 'Hung Trạch', 'Căn nhà biến thành một sinh vật sống đầy cạm bẫy.', 'Trạch Sát', 'Cố Địa Hệ', 'Quỷ Tướng', 'Tường biết thở, cửa biết ăn, căn nhà này đã sống dậy.', 'Tường biết thở, cửa biết ăn, căn nhà này đã sống dậy.', 'Đại thành của Trạch Hệ, căn nhà hấp thụ âm khí hàng trăm năm biến thành một quỷ thể khổng lồ.', 'Toàn bộ căn nhà hóa thành sinh vật: tường là thịt, cửa là miệng, cầu thang là ruột.', 'Nạn nhân bước vào bên trong sẽ bị căn nhà từ từ tiêu hóa như thức ăn.', '【Hung Trạch Vực】 — Kiến trúc bên trong căn nhà tự thay đổi không gian vô tận.', 'Nền móng trụ cột chính của căn nhà.', 'Chưa cập nhật', 'Có những căn nhà không phải để ở, mà là để nuốt chửng người vào.'),

-- Volume 13: Bản Ngã Hệ (Vô Diện Quỷ)
(61, 13, 'BẢN NGÃ HỆ', '十三 · VÔ DIỆN QUỶ', 'Mặt mất, tên còn. Tên mất, người cũng chẳng còn.', 'Sinh từ người bị rạch mặt, bị biến dạng khuôn mặt, bị cướp danh tính hoặc chết vô danh.', 'Bàn trang điểm rỉ máu; bóng trong gương không có mặt; mặt người sống mờ dần.', 'Người không mặt gọi đúng tên ngươi, chớ nhìn.', 'Thiên Diện Thành', 'Không gian đầy những chiếc gương soi phản chiếu vạn khuôn mặt.', 'Đoạt Diện Quỷ', 'Bản Ngã Hệ', 'Du Hồn', 'Khuôn mặt của ngươi rất đẹp... giờ nó là của ta.', 'Khuôn mặt của ngươi rất đẹp... giờ nó là của ta.', 'Người chết do bị lột da mặt hoặc bị hủy hoại nhan sắc trong ghen tuông.', 'Chuyên đi cướp và lột da mặt của người sống để đắp lên khuôn mặt trống rỗng của mình.', 'Nhìn thẳng vào khuôn mặt không có ngũ quan của nó → Bị lột mất da mặt ngay lập tức.', '【Đoạt Diện Vực】 — Không gian giăng kín những lớp da mặt người phơi khô.', 'Khuôn mặt nguyên bản bị hủy hoại của nó.', 'Chưa cập nhật', 'Đêm khuya soi gương thấy mặt mình mờ đi, Đoạt Diện Quỷ đang ở sau lưng.'),
(62, 13, 'BẢN NGÃ HỆ', '十三 · VÔ DIỆN QUỶ', 'Mặt mất, tên còn. Tên mất, người cũng chẳng còn.', 'Sinh từ người bị rạch mặt, bị biến dạng khuôn mặt, bị cướp danh tính hoặc chết vô danh.', 'Bàn trang điểm rỉ máu; bóng trong gương không có mặt; mặt người sống mờ dần.', 'Người không mặt gọi đúng tên ngươi, chớ nhìn.', 'Thiên Diện Thành', 'Không gian đầy những chiếc gương soi phản chiếu vạn khuôn mặt.', 'Hoán Diện Quỷ', 'Bản Ngã Hệ', 'Oán Hồn', 'Ngươi là hắn, hắn là ngươi, ai mới là kẻ sống?', 'Ngươi là hắn, hắn là ngươi, ai mới là kẻ sống?', 'Hình thành từ sự tráo đổi thân phận, giả mạo danh tính dẫn đến cái chết thảm khốc.', 'Tráo đổi khuôn mặt và thân phận giữa những người sống trong cùng một không gian.', 'Nạn nhân bị hoán đổi mặt sẽ mất đi ký ức của chính mình và gánh nhận tai họa của người khác.', '【Hoán Diện Vực】 — Không gian ảo ảnh khiến người sống không nhận ra nhau.', 'Sợi dây truyền thần ký ức nối giữa các nạn nhân.', 'Chưa cập nhật', 'Nhìn vào người thân nhưng thấy khuôn mặt lạ lẫm, hãy cẩn thận hoán diện.'),
(63, 13, 'BẢN NGÃ HỆ', '十三 · VÔ DIỆN QUỶ', 'Mặt mất, tên còn. Tên mất, người cũng chẳng còn.', 'Sinh từ người bị rạch mặt, bị biến dạng khuôn mặt, bị cướp danh tính hoặc chết vô danh.', 'Bàn trang điểm rỉ máu; bóng trong gương không có mặt; mặt người sống mờ dần.', 'Người không mặt gọi đúng tên ngươi, chớ nhìn.', 'Thiên Diện Thành', 'Không gian đầy những chiếc gương soi phản chiếu vạn khuôn mặt.', 'Tá Diện Quỷ', 'Bản Ngã Hệ', 'Lệ Quỷ', 'Mượn mặt người chết để trở về thăm người sống.', 'Mượn mặt người chết để trở về thăm người sống.', 'Vong hồn mượn khuôn mặt của người đã chết để quay về lừa dối người thân.', 'Giả dạng hoàn hảo người đã chết từ khuôn mặt đến giọng nói nhưng không có ký ức thật.', 'Nếu hỏi về ký ức thầm kín mà nó không trả lời được → Nó sẽ hóa sát tấn công.', '【Tá Diện Vực】 — Khung cảnh gia đình ấm áp ảo giả do quỷ tạo ra.', 'Điểm yếu ký ức thật sự của người chết.', 'Chưa cập nhật', 'Kẻ trở về từ cõi chết có thể mang khuôn mặt cũ nhưng không mang trái tim cũ.'),
(64, 13, 'BẢN NGÃ HỆ', '十三 · VÔ DIỆN QUỶ', 'Mặt mất, tên còn. Tên mất, người cũng chẳng còn.', 'Sinh từ người bị rạch mặt, bị biến dạng khuôn mặt, bị cướp danh tính hoặc chết vô danh.', 'Bàn trang điểm rỉ máu; bóng trong gương không có mặt; mặt người sống mờ dần.', 'Người không mặt gọi đúng tên ngươi, chớ nhìn.', 'Thiên Diện Thành', 'Không gian đầy những chiếc gương soi phản chiếu vạn khuôn mặt.', 'Kính Quỷ', 'Bản Ngã Hệ', 'Hung Sát', 'Hình trong gương động trước, người đứng trước gương chết sau.', 'Hình trong gương động trước, người đứng trước gương chết sau.', 'Oán hồn nhập vào chiếc gương cổ soi diện mạo người chết qua nhiều thế hệ.', 'Núp trong gương, bắt chước hành động của nạn nhân rồi tự động thay đổi hành vi để giết người.', 'Khi bóng trong gương di chuyển khác với người đứng trước gương, quy luật tử vong kích hoạt.', '【Kính Trung Vực】 — Thế giới đối xứng ngập tràn mảnh gương soi.', 'Chiếc gương gốc nguyên bản chứa bản thể quỷ.', 'Chưa cập nhật', 'Nửa đêm che vải đen lên gương là cách tốt nhất để tránh Kính Quỷ.'),
(65, 13, 'BẢN NGÃ HỆ', '十三 · VÔ DIỆN QUỶ', 'Mặt mất, tên còn. Tên mất, người cũng chẳng còn.', 'Sinh từ người bị rạch mặt, bị biến dạng khuôn mặt, bị cướp danh tính hoặc chết vô danh.', 'Bàn trang điểm rỉ máu; bóng trong gương không có mặt; mặt người sống mờ dần.', 'Người không mặt gọi đúng tên ngươi, chớ nhìn.', 'Thiên Diện Thành', 'Không gian đầy những chiếc gương soi phản chiếu vạn khuôn mặt.', 'Thiên Diện Quỷ', 'Bản Ngã Hệ', 'Quỷ Tướng', 'Ta có vạn khuôn mặt, ngươi muốn ta là ai?', 'Ta có vạn khuôn mặt, ngươi muốn ta là ai?', 'Đại thành của Vô Diện Hệ, nuốt chửng hàng ngàn khuôn mặt và bản ngã của nạn nhân.', 'Biến hóa liên tục thành bất kỳ ai, có khả năng sử dụng kỹ năng của những người nó đã nuốt.', 'Mỗi khuôn mặt thay đổi mang lại một tập thể quy luật tử vong khác nhau.', '【Thiên Diện Thành】 — Thành phố ngập tràn những bức tượng mất mặt.', 'Khuôn mặt nguyên bản đầu tiên bị lột mất dưới đáy sâu tâm trí.', 'Chưa cập nhật', 'Khi nhìn thấy Thiên Diện Quỷ, ngươi sẽ thấy khuôn mặt của chính mình trong đó.'),

-- Volume 14: Sơn Rừng Hệ (Sơn Quỷ)
(66, 14, 'SƠN RỪNG HỆ', '十四 · SƠN QUỶ', 'Người vào núi là khách. Người chết trong núi mới là chủ.', 'Sinh ra từ thợ sơn trảng chết lạc, cây cổ thụ nghìn năm tích âm, đá ngàn năm gieo quẻ, chướng khí độc.', 'Sương mù dày đặc không tan; tiếng thú hú gầm biến dị; cây cối tự dịch chuyển đường đi.', 'Trong núi nghe người thân gọi, chớ đi theo.', 'Sơn Quân Quốc', 'Cả ngọn núi biến thành cơ thể sống của ác quỷ.', 'Mộc Quỷ', 'Sơn Rừng Hệ', 'Du Hồn', 'Cành khô mọc rễ, xé thịt cắm xương.', 'Cành khô mọc rễ, xé thịt cắm xương.', 'Oán khí người chết dính vào cây khô, biến cây chết thành thực thể sống.', 'Điều khiển rễ cây và cành khô đâm xuyên qua cơ thể người sống làm phân bón.', 'Ai giậm chân lên rễ chính của nó sẽ bị rễ cây cuốn chặt kéo xuống lòng đất.', '【Mộc Lâm Vực】 — Rừng cây khô cạn tự động khép góc chặn đường thoát.', 'Trái tim bằng gỗ nằm ở lõi thân cây.', 'Chưa cập nhật', 'Rừng khô không gió mà cành đung đưa là Mộc Quỷ đang săn mồi.'),
(67, 14, 'SƠN RỪNG HỆ', '十四 · SƠN QUỶ', 'Người vào núi là khách. Người chết trong núi mới là chủ.', 'Sinh ra từ thợ sơn trảng chết lạc, cây cổ thụ nghìn năm tích âm, đá ngàn năm gieo quẻ, chướng khí độc.', 'Sương mù dày đặc không tan; tiếng thú hú gầm biến dị; cây cối tự dịch chuyển đường đi.', 'Trong núi nghe người thân gọi, chớ đi theo.', 'Sơn Quân Quốc', 'Cả ngọn núi biến thành cơ thể sống của ác quỷ.', 'Thụ Mị', 'Sơn Rừng Hệ', 'Oán Hồn', 'Cây cổ thụ thành tinh, giả tiếng người gọi bạn.', 'Cây cổ thụ thành tinh, giả tiếng người gọi bạn.', 'Cây cổ thụ nghìn năm hút quá nhiều thi thể người chết lạc hoặc máu muông thú.', 'Giả giọng nói của người thân nạn nhân phát ra từ đỉnh tán cây để dụ người leo lên.', 'Nghe tiếng gọi trong rừng mà bước đi theo → Sẽ bị dẫn lạc vào sâu trong đầm lầy chết.', '【Mê Lâm Vực】 — Bản đồ rừng cây xoay chuyển liên tục khiến la bàn mất tác dụng.', 'Phần gốc cây ôm lấy hài cốt cổ xưa nhất.', 'Chưa cập nhật', 'Đừng bao giờ leo lên những cây cổ thụ có hình thù giống người giữa rừng sâu.'),
(68, 14, 'SƠN RỪNG HỆ', '十四 · SƠN QUỶ', 'Người vào núi là khách. Người chết trong núi mới là chủ.', 'Sinh ra từ thợ sơn trảng chết lạc, cây cổ thụ nghìn năm tích âm, đá ngàn năm gieo quẻ, chướng khí độc.', 'Sương mù dày đặc không tan; tiếng thú hú gầm biến dị; cây cối tự dịch chuyển đường đi.', 'Trong núi nghe người thân gọi, chớ đi theo.', 'Sơn Quân Quốc', 'Cả ngọn núi biến thành cơ thể sống của ác quỷ.', 'Thạch Quỷ', 'Sơn Rừng Hệ', 'Lệ Quỷ', 'Đá núi mọc mắt, đè nát sinh linh.', 'Đá núi mọc mắt, đè nát sinh linh.', 'Bị thợ đá chết đè hoặc phu núi táng mạng dưới đá lở, oán khí nhập vào đá núi.', 'Khó di chuyển nhưng cực kỳ kiên cố, có thể tạo ra các đợt đá lăn, sạt lở đè nát kẻ thù.', 'Khi tiến vào vùng đá ngàn năm, đòn tấn công vật lý thông thường hoàn toàn vô hiệu.', '【Thạch Sơn Vực】 — Đất đá tự nhô lên tạo thành ngục đá giam hãm.', 'Mạch đá tích tụ oán khí thẫm màu đỏ bên trong.', 'Chưa cập nhật', 'Đá trên núi biết chớp mắt là điềm Thạch Quỷ sắp chuyển mình.'),
(69, 14, 'SƠN RỪNG HỆ', '十四 · SƠN QUỶ', 'Người vào núi là khách. Người chết trong núi mới là chủ.', 'Sinh ra từ thợ sơn trảng chết lạc, cây cổ thụ nghìn năm tích âm, đá ngàn năm gieo quẻ, chướng khí độc.', 'Sương mù dày đặc không tan; tiếng thú hú gầm biến dị; cây cối tự dịch chuyển đường đi.', 'Trong núi nghe người thân gọi, chớ đi theo.', 'Sơn Quân Quốc', 'Cả ngọn núi biến thành cơ thể sống của ác quỷ.', 'Chướng Quỷ', 'Sơn Rừng Hệ', 'Hung Sát', 'Hít một ngụm sương độc, ảo giác trọn đời không tan.', 'Hít một ngụm sương độc, ảo giác trọn đời không tan.', 'Sinh ra từ chướng khí thối rữa của vạn xác chết muông thú và con người trong rừng sâu.', 'Không tấn công trực tiếp, phát tán sương mù độc làm nạn nhân mất phương hướng, điên loạn.', 'Hít phải chướng khí → Nhìn thấy ảo giác kinh hoàng và tự lao đầu xuống vực thẳm.', '【Chướng Mù Vực】 — Tầm nhìn giảm xuống bằng không, không khí mang kịch độc.', 'Nhãn Chướng — Cụm khói đen đặc quánh nằm ở tâm sương mù.', 'Chưa cập nhật', 'Sương mù màu tím trên núi không phải là mây, đó là hơi thở của Chướng Quỷ.'),
(70, 14, 'SƠN RỪNG HỆ', '十四 · SƠN QUỶ', 'Người vào núi là khách. Người chết trong núi mới là chủ.', 'Sinh ra từ thợ sơn trảng chết lạc, cây cổ thụ nghìn năm tích âm, đá ngàn năm gieo quẻ, chướng khí độc.', 'Sương mù dày đặc không tan; tiếng thú hú gầm biến dị; cây cối tự dịch chuyển đường đi.', 'Trong núi nghe người thân gọi, chớ đi theo.', 'Sơn Quân Quốc', 'Cả ngọn núi biến thành cơ thể sống của ác quỷ.', 'Sơn Quân', 'Sơn Rừng Hệ', 'Quỷ Tướng', 'Khi Sơn Quân thức giấc, núi không còn cho người rời đi.', 'Khi Sơn Quân thức giấc, núi không còn cho người rời đi.', 'Đại thành của Sơn Hệ, chúa tể núi rừng hòa làm một với toàn bộ không gian ngọn núi.', 'Cả ngọn núi là thân thể: Cây là tay, đá là xương, sương là hơi thở, thú dữ là tay sai.', 'Mọi luật lệ sinh tồn trong núi đều do Sơn Quân định đoạt.', '【Sơn Quân Quốc】 — Cả ngọn núi bị cô lập hoàn toàn khỏi thế giới thực.', 'Ngang lưng núi — Nơi đặt hang động nguyên thủy nhất chứa linh hạch ngọn núi.', 'Chưa cập nhật', 'Núi rung chuyển không phải động đất, là Sơn Quân đang trở mình.'),

-- Volume 15: Dục Vọng Hệ (Ngạ Quỷ)
(71, 15, 'DỤC VỌNG HỆ', '十五 · NGẠ QUỶ', 'Bụng đói thì tìm thức ăn. Quỷ đói ăn cả sinh khí.', 'Sinh từ người chết đói, chết khát, kẻ cực kỳ tham lam tài bảo, quyền lực, dục vọng lúc sống.', 'Mùi hôi thối của dạ dày mục; đồ ăn tự biến thành tro bụi; cảm giác đói khát cào xé ruột gan.', 'Thấy kẻ đói nhìn thức ăn, chớ cho nó ăn bằng tay mình.', 'Đại Đói', 'Khuếch đại toàn bộ lòng tham và dục vọng trong tâm trí nạn nhân.', 'Châm Khẩu Quỷ', 'Dục Vọng Hệ', 'Du Hồn', 'Bụng to như núi, cổ nhỏ như kim, thức ăn vào miệng hóa thành lửa.', 'Bụng to như núi, cổ nhỏ như kim, thức ăn vào miệng hóa thành lửa.', 'Kẻ lúc sống keo kiệt, tham nhũng, cướp đoạt đồ ăn của người khác khiến người khác chết đói.', 'Cực kỳ đói khát nhưng không thể nuốt thức ăn. Khi đưa thức ăn vào miệng lập tức hóa thành lửa bùng cháy.', 'Sự thèm khát khiến nó điên cuồng tấn công người sống để cướp giật sinh khí.', '【Đói Đường Vực】 — Nạn nhân bước vào cảm thấy dạ dày xé rách vì đói khát.', 'Chiếc cổ họng nhỏ như que kim.', 'Chưa cập nhật', 'Bụng nó to béo nhưng cổ họng lại nhỏ đến mức không nuốt nổi một hạt gạo.'),
(72, 15, 'DỤC VỌNG HỆ', '十五 · NGẠ QUỶ', 'Bụng đói thì tìm thức ăn. Quỷ đói ăn cả sinh khí.', 'Sinh từ người chết đói, chết khát, kẻ cực kỳ tham lam tài bảo, quyền lực, dục vọng lúc sống.', 'Mùi hôi thối của dạ dày mục; đồ ăn tự biến thành tro bụi; cảm giác đói khát cào xé ruột gan.', 'Thấy kẻ đói nhìn thức ăn, chớ cho nó ăn bằng tay mình.', 'Đại Đói', 'Khuếch đại toàn bộ lòng tham và dục vọng trong tâm trí nạn nhân.', 'Thực Huyết Quỷ', 'Dục Vọng Hệ', 'Oán Hồn', 'Máu tươi ngon hơn rượu ngon, một giọt cũng không bỏ.', 'Máu tươi ngon hơn rượu ngon, một giọt cũng không bỏ.', 'Ngạ Quỷ tiến hóa chuyên đi liếm và uống máu người sống để khỏa lấp cơn đói.', 'Rình rập người có vết thương hở, hút sạch máu qua vết thương khiến nạn nhân khô xác.', 'Càng ngửi thấy mùi máu tươi chảy ra ngoài, tốc độ di chuyển càng kinh hoàng.', '【Thực Huyết Vực】 — Mùi máu làm kích thích cơn thèm máu của mọi sinh linh.', 'Môi và chiếc lưỡi dài nhọn.', 'Chưa cập nhật', 'Thực Huyết Quỷ không phải Huyết Quỷ. Huyết Quỷ giết vì sát nghiệp, Ngạ Quỷ uống vì đói khát.'),
(73, 15, 'DỤC VỌNG HỆ', '十五 · NGẠ QUỶ', 'Bụng đói thì tìm thức ăn. Quỷ đói ăn cả sinh khí.', 'Sinh từ người chết đói, chết khát, kẻ cực kỳ tham lam tài bảo, quyền lực, dục vọng lúc sống.', 'Mùi hôi thối của dạ dày mục; đồ ăn tự biến thành tro bụi; cảm giác đói khát cào xé ruột gan.', 'Thấy kẻ đói nhìn thức ăn, chớ cho nó ăn bằng tay mình.', 'Đại Đói', 'Khuếch đại toàn bộ lòng tham và dục vọng trong tâm trí nạn nhân.', 'Thực Nhục Quỷ', 'Dục Vọng Hệ', 'Lệ Quỷ', 'Ăn thịt người sống, mọc lại thịt mình.', 'Ăn thịt người sống, mọc lại thịt mình.', 'Kẻ tàn bạo ăn thịt người trong những năm hoảng loạn đói kém rồi chết vì bội thực.', 'Ăn thịt người sống để tái tạo lại thân thể rữa nát của mình.', 'Nuốt một phần cơ thể nạn nhân → Có khả năng biến thành hình dạng của nạn nhân đó.', '【Nhục Thành Vực】 — Không gian đập phập phồng như bên trong một dạ dày khổng lồ.', 'Chiếc dạ dày ngâm trong độc tố tử khí.', 'Chưa cập nhật', 'Nó ăn thịt ngươi không chỉ để no, mà để trở thành ngươi.'),
(74, 15, 'DỤC VỌNG HỆ', '十五 · NGẠ QUỶ', 'Bụng đói thì tìm thức ăn. Quỷ đói ăn cả sinh khí.', 'Sinh từ người chết đói, chết khát, kẻ cực kỳ tham lam tài bảo, quyền lực, dục vọng lúc sống.', 'Mùi hôi thối của dạ dày mục; đồ ăn tự biến thành tro bụi; cảm giác đói khát cào xé ruột gan.', 'Thấy kẻ đói nhìn thức ăn, chớ cho nó ăn bằng tay mình.', 'Đại Đói', 'Khuếch đại toàn bộ lòng tham và dục vọng trong tâm trí nạn nhân.', 'Thực Khí Quỷ', 'Dục Vọng Hệ', 'Hung Sát', 'Thức ăn của nó là tuổi thọ và nhiệt độ cơ thể ngươi.', 'Thức ăn của nó là tuổi thọ và nhiệt độ cơ thể ngươi.', 'Sinh ra từ kẻ tham sống sợ chết, dùng mọi thủ đoạn để kéo dài hơi tàn lúc lâm chung.', 'Không ăn vật chất, chỉ đứng sau lưng hút dần dương khí, sinh lực và tuổi thọ nạn nhân.', 'Nạn nhân không hề nhận ra bị hút sinh khí cho đến khi cơ thể gầy còm và héo hắt chết.', '【Khí Tận Vực】 — Không gian lạnh ngắt làm hạ nhiệt độ cơ thể xuống cực điểm.', 'Lỗ mũi và miệng dùng để hít khí.', 'Chưa cập nhật', 'Sáng dậy thấy tóc bạc thêm nhiều sợi, đêm qua có lẽ Thực Khí Quỷ đã đứng đầu giường.'),
(75, 15, 'DỤC VỌNG HỆ', '十五 · NGẠ QUỶ', 'Bụng đói thì tìm thức ăn. Quỷ đói ăn cả sinh khí.', 'Sinh từ người chết đói, chết khát, kẻ cực kỳ tham lam tài bảo, quyền lực, dục vọng lúc sống.', 'Mùi hôi thối của dạ dày mục; đồ ăn tự biến thành tro bụi; cảm giác đói khát cào xé ruột gan.', 'Thấy kẻ đói nhìn thức ăn, chớ cho nó ăn bằng tay mình.', 'Đại Đói', 'Khuếch đại toàn bộ lòng tham và dục vọng trong tâm trí nạn nhân.', 'Thực Tinh Quỷ', 'Dục Vọng Hệ', 'Quỷ Vương', 'Ngạ Quỷ đáng sợ không phải vì nó đói. Mà bởi nó biết ngươi đang đói thứ gì.', 'Ngạ Quỷ đáng sợ không phải vì nó đói. Mà bởi nó biết ngươi đang đói thứ gì.', 'Đỉnh cao của Ngạ Quỷ Hệ, ăn tinh khí, ham muốn và mọi loại dục vọng của con người.', 'Khuếch đại lòng tham vốn có trong tâm nạn nhân (tham tiền, tham quyền, tham tình) rồi nuốt chửng linh hồn.', 'Nạn nhân càng có nhiều tham vọng bùng cháy, Thực Tinh Quỷ hấp thụ càng nhanh.', '【Đại Đói Vực】 — Nơi kẻ nghèo đói tiền, kẻ quyền lực đói quyền, kẻ cô đơn đói tình cảm.', 'Sự thỏa mãn tuyệt đối (Tâm Vô Dục Vọng).', 'Chưa cập nhật', 'Thứ giết chết ngươi trong vực Đại Đói không phải ác quỷ, mà là lòng tham của chính ngươi.');
